                        '     "//  Visual のみ: Label に統合後 Zone の上下限 / 幅 (USD) を表示 (初期 ON、表示だけ)。\\n" + HDR5 + '
                        '"。\\n"),\n'
                        '] + ZONE_EDITS5\n'
                        'STRATEGY_EDITS5 = [\n'
                        '    ("header",\n'
                        '     "//  資金管理 (XA-2)・売買 / 取消 / TP / 建値の処理とタイミング・XA-3 の採用初期値は変更なし。\\n",\n'
                        '     "//  資金管理 (XA-2)・売買 / 取消 / TP / 建値の処理とタイミング・XA-3 の採用初期値は変更なし。\\n" + HDR5 + "、\\n"\n'
                        '     "//  建値移動 ON・Trigger 15 USD。Zone 生成・採点・統合条件・Entry・数量・注文 / 取消 / TP / '
                        '建値の判定と処理順は変えない。\\n"),\n'
                        '    ("text",\n'
                        '     "//  Entry C: Candle Pattern、Short Only、SL Buffer 1.5、固定 RR 1.5、反対側 Zone TP OFF、建値移動 '
                        'OFF (Trigger は現行値のまま)。\\n",\n'
                        '     "//  Entry C: Candle Pattern、Short Only、SL Buffer 1.5、固定 RR 1.5、反対側 Zone TP OFF、建値移動 '
                        '(XA-5 で ON・Trigger 15 に変更)。\\n"),\n'
                        '] + ZONE_EDITS5 + [\n'
                        '    ("default",\n'
                        '     \'stBE = input.bool(false, "Breakeven Stop", group = G_STT)\\n\',\n'
                        '     \'stBE = input.bool(true, "Breakeven Stop", group = G_STT)\\n\'),\n'
                        '    ("default",\n'
                        '     \'stBEDist = input.float(10.0, "Breakeven Trigger ($)", minval = 0.0, step = 0.5, '
                        "group = G_STT)\\n',\n"
                        '     \'stBEDist = input.float(15.0, "Breakeven Trigger ($)", minval = 0.0, step = 0.5, '
                        "group = G_STT)\\n'),\n"
                        ']\n'
                        '\n'
                        '\n'
                        '# ---- XA-6: Role Reversal Mode (Engine library version 2; Visual / Strategy after XA-5) '
                        '----------------------------------\n'
                        '#  Separates "role change" from "retest reversal confirmation". ZoneCfg.roleOnBreak (Engine '
                        'default false = the previous\n'
                        '#  Retest Confirmed behaviour; the previous f_updateTrack branch stays byte-identical under '
                        '`else if evalBar`).\n'
                        "#  Confirmed Break (roleOnBreak = true, the scripts' new default): on a confirmed "
                        'Break-feed bar, RESIST with close > top +\n'
                        '#  breakBuffer becomes SUPPORT (SUPPORT with close < bottom - breakBuffer becomes RESIST) '
                        'at once (strict compare, no BROKEN\n'
                        '#  wait); breakDir / retested keep the reversal confirmation pending separately (flipped '
                        'stays false). The Break bar is not a\n'
                        '#  retest; a later confirmed bar overlapping the zone records the retest; a still later bar '
                        'beyond flipConfirmDist confirms\n'
                        '#  (flipped, Flip event, Flip Bonus) once. An opposite clear Break while pending discards '
                        'the pending confirmation and starts\n'
                        '#  the new direction (resetOnReclaim is not used in this mode). No natural role reversal, '
                        'no Track re-creation.\n'
                        '#  strip_engine6 / strip_*6 reverse only these.\n'
                        'IMPORT_XAE2 = "import sekine3310/ZoneEnginePracticalXAUUSD/2 as zn\\n"\n'
                        '# Library version 2 of ZoneEnginePracticalXAUUSD (/1 stays published). If TradingView '
                        'assigns another number, change\n'
                        '# IMPORT_XAE2 and rebuild (python3 tests/xa_build.py).\n'
                        'ROLE_NEW = (\n'
                        '    "    //  XA-6 Confirmed Break (c.roleOnBreak): 明確な Break (確定 Break 評価足の終値、strict) '
                        'のその足で新しい役割にする\\n"\n'
                        '    "    //    (BROKEN では待たせない)。Retest → Flip Confirm の反転確認は breakDir / retested '
                        'で別に保持し、flipped は確認成立まで\\n"\n'
                        '    "    //    false。Break 足自身は Retest にせず、Retest を記録した足では確認しない。確認待ち中に反対方向の明確な Break が\\n"\n'
                        '    "    //    成立したら前の確認待ちを破棄して新しい方向へ切り替える (resetOnReclaim はこの方式では使わない)。\\n"\n'
                        '    "    if evalBar and c.roleOnBreak\\n"\n'
                        '    "        if evalState == ST_RESIST and bc > t.top + c.breakBuffer\\n"\n'
                        '    "            t.state    := ST_SUPPORT\\n"\n'
                        '    "            t.breakDir := 1\\n"\n'
                        '    "            t.breakBar := bar_index\\n"\n'
                        '    "            t.retested := false\\n"\n'
                        '    "            t.flipped  := false\\n"\n'
                        '    "            t.flipDir  := 0\\n"\n'
                        '    "            handled    := true\\n"\n'
                        '    "            ev := 1\\n"\n'
                        '    "        else if evalState == ST_SUPPORT and bc < t.bottom - c.breakBuffer\\n"\n'
                        '    "            t.state    := ST_RESIST\\n"\n'
                        '    "            t.breakDir := -1\\n"\n'
                        '    "            t.breakBar := bar_index\\n"\n'
                        '    "            t.retested := false\\n"\n'
                        '    "            t.flipped  := false\\n"\n'
                        '    "            t.flipDir  := 0\\n"\n'
                        '    "            handled    := true\\n"\n'
                        '    "            ev := -1\\n"\n'
                        '    "        else if t.breakDir == 1\\n"\n'
                        '    "            handled := true\\n"\n'
                        '    "            if not t.retested\\n"\n'
                        '    "                if bl <= t.top and bh >= t.bottom\\n"\n'
                        '    "                    t.retested := true\\n"\n'
                        '    "            else if bc >= t.top + c.flipConfirmDist\\n"\n'
                        '    "                t.flipped  := true\\n"\n'
                        '    "                t.flipDir  := 1\\n"\n'
                        '    "                t.breakDir := 0\\n"\n'
                        '    "                t.retested := false\\n"\n'
                        '    "                ev := 2\\n"\n'
                        '    "        else if t.breakDir == -1\\n"\n'
                        '    "            handled := true\\n"\n'
                        '    "            if not t.retested\\n"\n'
                        '    "                if bh >= t.bottom and bl <= t.top\\n"\n'
                        '    "                    t.retested := true\\n"\n'
                        '    "            else if bc <= t.bottom - c.flipConfirmDist\\n"\n'
                        '    "                t.flipped  := true\\n"\n'
                        '    "                t.flipDir  := -1\\n"\n'
                        '    "                t.breakDir := 0\\n"\n'
                        '    "                t.retested := false\\n"\n'
                        '    "                ev := -2\\n"\n'
                        '    "    else if evalBar\\n")\n'
                        'ENGINE_EDITS6 = [\n'
                        '    ("header",\n'
                        '     "//    以下の「GBPJPY 派生」等は移植元の説明 (履歴)。\\n",\n'
                        '     "//  ★ XA-6 (Library version 2): Role Reversal Mode (ZoneCfg.roleOnBreak)。false (既定) = '
                        'Retest Confirmed = version 1 と\\n"\n'
                        '     "//    同じ処理 (Break → BROKEN → Retest → Flip Confirm で新しい役割)。true = Confirmed Break = '
                        '明確な Break の足で新しい役割にし、\\n"\n'
                        '     "//    Retest → Flip Confirm の反転確認 (flipped / Flip イベント / Flip Bonus) は別に継続する。\\n"\n'
                        '     "//    以下の「GBPJPY 派生」等は移植元の説明 (履歴)。\\n"),\n'
                        '    ("cfg",\n'
                        '     "    bool   resetOnReclaim     = true\\n",\n'
                        '     "    bool   resetOnReclaim     = true\\n"\n'
                        '     "    bool   roleOnBreak        = false   // XA-6: false = Retest Confirmed (version 1 '
                        'と同じ) / true = Confirmed Break\\n"),\n'
                        '    ("role",\n'
                        '     "    if evalBar\\n        if evalState == ST_RESIST and bc > t.top + '
                        'c.breakBuffer\\n",\n'
                        '     ROLE_NEW + "        if evalState == ST_RESIST and bc > t.top + c.breakBuffer\\n"),\n'
                        ']\n'
                        'HDR6 = ("//  XA-6: Role Reversal Mode (初期 Confirmed Break。Engine ZoneEnginePracticalXAUUSD '
                        'version 2): 確定した Break 評価足の終値が\\n"\n'
                        '        "//  top + Break Buffer より上 / bottom - Break Buffer より下でその足から Support / Resistance '
                        '候補 (BROKEN で待たない)。\\n"\n'
                        '        "//  Retest → Flip Confirm の反転確認 (Flip イベント・Flip Bonus) は別に継続。Retest Confirmed = '
                        '変更前の方式 (比較・切り戻し用)。\\n"\n'
                        '        "//  成績への影響は未確認。数値・Zone 生成 / 採点・上位足取得・Break feed は変えない。\\n")\n'
                        'ZONE_EDITS6 = [\n'
                        '    ("import", IMPORT_XAE, IMPORT_XAE2),\n'
                        '    ("input",\n'
                        '     \'resetOnReclaim = input.bool(true,  "Reset Broken on Reclaim", group = G_BF)\\n\',\n'
                        '     \'resetOnReclaim = input.bool(true,  "Reset Broken on Reclaim", group = G_BF,\\n\'\n'
                        '     \'     tooltip = "Role Reversal Mode = Retest Confirmed のときだけ使う (BROKEN '
                        '中に反対側へ明確に戻ったら役割を初期判定に戻す)。\\\\n" +\\n\'\n'
                        '     \'     "Confirmed Break では使わない (反対方向の明確な Break がそのまま役割を切り替え、確認待ちを破棄する)。")\\n\'\n'
                        '     \'roleMode = input.string("Confirmed Break", "Role Reversal Mode", options = ["Retest '
                        'Confirmed", "Confirmed Break"], group = G_BF,\\n\'\n'
                        '     \'     tooltip = "Confirmed Break (初期): Break 評価足の確定終値が top + Break Buffer より上なら '
                        'Support 候補、bottom - Break Buffer\\\\n" +\\n\'\n'
                        '     \'     "より下なら Resistance 候補にその足で切り替える (等値は不成立。BROKEN で待たない)。Retest → Flip Confirm '
                        'の反転確認は別に継続し、\\\\n" +\\n\'\n'
                        '     \'     "Flip イベント・Flip Bonus は確認成立時だけ。Retest Confirmed: 変更前の方式 (Break → BROKEN → '
                        'Retest → Flip Confirm)。比較・切り戻し用。")\\n\'),\n'
                        '    ("cfg",\n'
                        '     "zoneCfg.resetOnReclaim       := resetOnReclaim\\n",\n'
                        '     "zoneCfg.resetOnReclaim       := resetOnReclaim\\n"\n'
                        '     "zoneCfg.roleOnBreak          := roleMode == \\"Confirmed Break\\"\\n"),\n'
                        ']\n'
                        'VISUAL_EDITS6 = [\n'
                        '    ("header", "//  1 つの根拠として数える)。\\n", "//  1 つの根拠として数える)。\\n" + HDR6),\n'
                        '] + ZONE_EDITS6\n'
                        'STRATEGY_EDITS6 = [\n'
                        '    ("header",\n'
                        '     "//  建値移動 ON・Trigger 15 USD。Zone 生成・採点・統合条件・Entry・数量・注文 / 取消 / TP / '
                        '建値の判定と処理順は変えない。\\n",\n'
                        '     "//  建値移動 ON・Trigger 15 USD。Zone 生成・採点・統合条件・Entry・数量・注文 / 取消 / TP / '
                        '建値の判定と処理順は変えない。\\n"\n'
                        '     + HDR6 + "//  Strategy: 新しい役割の Zone を Retest 前から候補評価できる (発注は従来どおり Entry A〜D '
                        'の条件が必要)。\\n"),\n'
                        '] + ZONE_EDITS6\n'
                        '\n'
                        '\n'
                        '# ---- XA-7: Entry Timing = SATS Pullback (Strategy only; after XA-6) '
                        '---------------------------------------------------\n'
                        '#  Current (default) keeps the previous order path byte for byte (the new branches are `if '
                        'stSats ... else if <old>`).\n'
                        '#  SATS Pullback (Entry C only; other Entry Modes stop with runtime.error): when Entry C '
                        'would place its market order, a single\n'
                        '#  wait is prepared instead (Track, side, prep bar / bar end time, P0 = that close, SL0 = '
                        'the existing SL, TP0 = the existing\n'
                        '#  f_stTp result at P0). From the next confirmed 5M bar: cancel first (wait >= limit '
                        "minutes of wall clock from the prep bar's\n"
                        '#  end / Track gone / no longer a same-side candidate with Strong eligibility / SL0 '
                        'reached), then the SATS line nearest to the\n'
                        '#  previous close among LINE1 / LINE2 / STB of the previous bar (Long: SL0 < L < P0 and L < '
                        'prev close; Short mirrored; ties\n'
                        '#  LINE1 -> LINE2 -> STB), touched (low <= L <= high) and closed back (Long close > L, SL0 '
                        '< close < P0; Short mirrored) on that\n'
                        '#  bar -> market order, qty = f_stQty(side, close, SL0). On the fill TP = TP0 (fixed; set '
                        'at the existing fill-confirmation\n'
                        '#  time); a fill on the wrong side of SL0 / TP0 is closed at market (no TP), never treated '
                        'as a normal entry.\n'
                        '#  f_satBand() is the SATS source function byte for byte (tests/sats_src/f_satBand.txt), '
                        'computed on every bar at global scope.\n'
                        'SATS_FN = open(os.path.join(ROOT, "tests", "sats_src", "f_satBand.txt"), '
                        'encoding="utf-8").read()\n'
                        'SATS_INPUTS = (\n'
                        '    \'var string G_STW = "03 · Strategy Entry Timing (SATS)"\\n\'\n'
                        '    \'stTiming = input.string("Current", "Entry Timing", options = ["Current", "SATS '
                        'Pullback"], group = G_STW,\\n\'\n'
                        '    \'     tooltip = "Current (初期): 変更前の発注方式。\\\\n" +\\n\'\n'
                        '    \'     "SATS Pullback: Entry C が発注する条件を満たした足で発注せず待機を始め、次の 5分足以降に SATS 線 (LINE1 / LINE2 '
                        '/ STB) への\\\\n" +\\n\'\n'
                        '    \'     "接触と終値での戻りを確認してから成行で発注する。SL0 / TP0 は準備時に固定 (約定後に TP を作り直さない)。\\\\n" +\\n\'\n'
                        '    \'     "Entry C 専用: 他の Entry Mode と組み合わせると停止して表示する (黙って別動作にしない)。")\\n\'\n'
                        '    \'stSatsWait = input.int(240, "SATS · 待機期限 (分)", minval = 1, group = G_STW,\\n\'\n'
                        '    \'     tooltip = "準備した 5分足の終了時刻からの実時間。この分数以上になった確定評価時点で取消 (週末・欠損・時間帯外も時計は止めない)。")\\n\'\n'
                        '    \'stSatsShow = input.bool(true, "SATS · 線を表示", group = G_STW)\\n\')\n'
                        'SATS_GLOBAL = (\n'
                        '    "\\n// ---- XA-7 · SATS (SAT BAND LINE1 / LINE2 / STB) '
                        '---------------------------------------------------------------------\\n"\n'
                        '    "//  f_satBand() は SATS 移植元 (SAT BAND Reconstruction Test) の関数を一字一句そのまま使う '
                        '(tests/sats_src/f_satBand.txt)。\\n"\n'
                        '    "//  待機の有無にかかわらず毎バー グローバルで計算する。色・バンド状態は Entry 判定に使わない。\\n"\n'
                        '    "bool stSats = stTiming == \\"SATS Pullback\\"\\n"\n'
                        '    "if stSats and not stModeC\\n"\n'
                        '    "    runtime.error(\\"Entry Timing = SATS Pullback は Entry Mode C: Candle Pattern 専用です '
                        '(他の Entry Mode は対象外)。\\")\\n"\n'
                        '    "\\n" + SATS_FN + "\\n"\n'
                        '    "[satL1, satL2, satStb, satD1, satD2, satSD, satBand, satBasis, satCommon, satAtr, '
                        'satA1, satA2] = f_satBand()\\n"\n'
                        '    "\\n"\n'
                        '    "// 足 t の判定に使う線: 足 t-1 で確定した 3 本の値と前足終値だけで選ぶ (足 t の値は使わない)。\\n"\n'
                        '    "//  Long: SL0 < L < P0 かつ L < 前足終値 / Short: SL0 > L > P0 かつ L > 前足終値。前足終値に最も近い線、同距離は '
                        'LINE1 -> LINE2 -> STB。\\n"\n'
                        '    "//  戻り値 [線の種類 (1 / 2 / 3、無ければ 0), 線の価格 (無ければ na)]。na の線は候補にしない。\\n"\n'
                        '    "f_satPick(int side, float p0, float sl0, float pc, float l1, float l2, float l3) '
                        '=>\\n"\n'
                        '    "    int   bk = 0\\n"\n'
                        '    "    float bp = na\\n"\n'
                        '    "    float bd = na\\n"\n'
                        '    "    for k = 1 to 3\\n"\n'
                        '    "        float v = k == 1 ? l1 : k == 2 ? l2 : l3\\n"\n'
                        '    "        bool ok = not na(v) and not na(pc) and (side == 1 ? (v > sl0 and v < p0 and v '
                        '< pc) : (v < sl0 and v > p0 and v > pc))\\n"\n'
                        '    "        if ok\\n"\n'
                        '    "            float d = math.abs(pc - v)\\n"\n'
                        '    "            if bk == 0 or d < bd\\n"\n'
                        '    "                bk := k\\n"\n'
                        '    "                bp := v\\n"\n'
                        '    "                bd := d\\n"\n'
                        '    "    [bk, bp]\\n")\n'
                        'SATS_VARS = (\n'
                        '    "// XA-7 SATS Pullback の待機 (全体で 1 件) と確認用の記録\\n"\n'
                        '    "var int   pwState  = 0       // 0 = 待機なし / 1 = 待機中\\n"\n'
                        '    "var int   pwSide   = 0\\n"\n'
                        '    "var int   pwTrack  = -1\\n"\n'
                        '    "var int   pwBar    = na\\n"\n'
                        '    "var int   pwEndT   = na      // 準備した 5分足の終了時刻 (期限の起点)\\n"\n'
                        '    "var float pwP0     = na\\n"\n'
                        '    "var float pwSL0    = na\\n"\n'
                        '    "var float pwTP0    = na\\n"\n'
                        '    "var float oTP0     = na      // SATS で発注した注文の TP0 (約定確認時の TP)\\n"\n'
                        '    "var float pwRRPrep = na\\n"\n'
                        '    "var float pwRRPlan = na\\n"\n'
                        '    "var float pwRRFill = na\\n"\n'
                        '    "var int   pwNPrep  = 0\\n"\n'
                        '    "var int   pwNOrder = 0\\n"\n'
                        '    "var int   pwNExp   = 0\\n"\n'
                        '    "var int   pwNTrk   = 0\\n"\n'
                        '    "var int   pwNZone  = 0\\n"\n'
                        '    "var int   pwNSL    = 0\\n"\n'
                        '    "var int   pwNBad   = 0\\n"\n'
                        '    "int   pwEv    = 0          // この足のイベント: 1 = 準備 / 2 = 発注 / -1 期限 / -2 Track 消失 / -3 '
                        '候補・Strong 資格なし / -4 SL0 到達\\n"\n'
                        '    "int   pwLineK = 0          // この足の判定に使った線 (1 = LINE1 / 2 = LINE2 / 3 = STB / 0 = '
                        'なし)\\n"\n'
                        '    "float pwLineP = na         // その線の価格 (足 t-1 の確定値)\\n")\n'
                        'SATS_FILL = (\n'
                        '    "    // (2b\') XA-7 SATS Pullback: TP は準備時の TP0 のまま (実約定価格から作り直さない)。設定は既存どおり約定確認時。\\n"\n'
                        '    "    //   実約定が SL0 / TP0 の不適切な側 (risk <= 0 または TP0 までの距離 <= 0) なら TP を置かず成行決済 '
                        '(正常約定として扱わない)\\n"\n'
                        '    "    if fillNow and stSats\\n"\n'
                        '    "        float riskS = oSide * (oFill - oSL)\\n"\n'
                        '    "        float rewS  = oSide * (oTP0 - oFill)\\n"\n'
                        '    "        pwRRFill := riskS > 0 ? rewS / riskS : na\\n"\n'
                        '    "        if riskS > 0 and rewS > 0\\n"\n'
                        '    "            oTP   := oTP0\\n"\n'
                        '    "            oStop := oSL\\n"\n'
                        '    "            strategy.exit(oXid, oEid, stop = oStop, limit = oTP)\\n"\n'
                        '    "        else\\n"\n'
                        '    "            strategy.close(oEid)\\n"\n'
                        '    "            oState := 3\\n"\n'
                        '    "            pwNBad += 1\\n"\n'
                        '    "    else if fillNow\\n")\n'
                        'SATS_WAIT = (\n'
                        '    "    // (3b) XA-7 SATS Pullback の待機判定 (準備足の次の足から)。取消を反発より優先する\\n"\n'
                        '    "    //   取消: 期限 (準備足の終了時刻からの実時間) / Track 消失 / 同方向の候補 (Strong 資格) でない / SL0 到達。使用済み '
                        'Track にはしない\\n"\n'
                        '    "    //   判定: 足 t-1 の確定線から選んだ L に足 t が接触し (low <= L <= high)、終値が戻る (Long: close > L、SL0 '
                        '< close < P0)\\n"\n'
                        '    "    bool  pwCancelBar = false\\n"\n'
                        '    "    if stSats and pwState == 1 and bar_index > pwBar\\n"\n'
                        '    "        bool zOK = false\\n"\n'
                        '    "        int  nc  = array.size(cur)\\n"\n'
                        '    "        if nc > 0\\n"\n'
                        '    "            for k = 0 to nc - 1\\n"\n'
                        '    "                StCand x = array.get(cur, k)\\n"\n'
                        '    "                if x.track == pwTrack and x.side == pwSide\\n"\n'
                        '    "                    zOK := true\\n"\n'
                        '    "        int why = 0\\n"\n'
                        '    "        if time_close - pwEndT >= stSatsWait * 60000\\n"\n'
                        '    "            why := -1\\n"\n'
                        '    "        else if array.indexof(curTrk, pwTrack) < 0\\n"\n'
                        '    "            why := -2\\n"\n'
                        '    "        else if not zOK\\n"\n'
                        '    "            why := -3\\n"\n'
                        '    "        else if pwSide == 1 ? low <= pwSL0 : high >= pwSL0\\n"\n'
                        '    "            why := -4\\n"\n'
                        '    "        if why != 0\\n"\n'
                        '    "            pwState     := 0\\n"\n'
                        '    "            pwCancelBar := true\\n"\n'
                        '    "            pwEv        := why\\n"\n'
                        '    "            pwNExp  += why == -1 ? 1 : 0\\n"\n'
                        '    "            pwNTrk  += why == -2 ? 1 : 0\\n"\n'
                        '    "            pwNZone += why == -3 ? 1 : 0\\n"\n'
                        '    "            pwNSL   += why == -4 ? 1 : 0\\n"\n'
                        '    "        else\\n"\n'
                        '    "            [lk, lp] = f_satPick(pwSide, pwP0, pwSL0, close[1], satL1[1], satL2[1], '
                        'satStb[1])\\n"\n'
                        '    "            pwLineK := lk\\n"\n'
                        '    "            pwLineP := lp\\n"\n'
                        '    "            bool hit = lk != 0 and low <= lp and lp <= high and (pwSide == 1 ? (close '
                        '> lp and close > pwSL0 and close < pwP0) : (close < lp and close < pwSL0 and close > '
                        'pwP0))\\n"\n'
                        '    "            if hit and stSessOK and oState == 0\\n"\n'
                        '    "                float q = f_stQty(pwSide, close, pwSL0)\\n"\n'
                        '    "                if not na(q)\\n"\n'
                        '    "                    oSeq    += 1\\n"\n'
                        '    "                    oEid    := (pwSide == 1 ? \\"L\\" : \\"S\\") + '
                        'str.tostring(oSeq)\\n"\n'
                        '    "                    oXid    := oEid + \\" SL/TP\\"\\n"\n'
                        '    "                    oSide   := pwSide\\n"\n'
                        '    "                    oTrack  := pwTrack\\n"\n'
                        '    "                    oLimit  := false\\n"\n'
                        '    "                    oL      := na\\n"\n'
                        '    "                    oSL     := pwSL0\\n"\n'
                        '    "                    oStop   := pwSL0\\n"\n'
                        '    "                    oTP     := na\\n"\n'
                        '    "                    oTP0    := pwTP0\\n"\n'
                        '    "                    oFill   := na\\n"\n'
                        '    "                    oBE     := false\\n"\n'
                        '    "                    oClosed := strategy.closedtrades\\n"\n'
                        '    "                    oState  := 1\\n"\n'
                        '    "                    strategy.entry(oEid, pwSide == 1 ? strategy.long : strategy.short, '
                        'qty = q)\\n"\n'
                        '    "                    strategy.exit(oXid, oEid, stop = oSL)\\n"\n'
                        '    "                    pwRRPlan := pwSide * (pwTP0 - close) / (pwSide * (close - '
                        'pwSL0))\\n"\n'
                        '    "                    pwRRFill := na\\n"\n'
                        '    "                    pwState  := 0\\n"\n'
                        '    "                    pwEv     := 2\\n"\n'
                        '    "                    pwNOrder += 1\\n"\n'
                        '    "\\n")\n'
                        'SATS_PREP = (\n'
                        '    "            if stSats\\n"\n'
                        '    "                // XA-7: Entry C が発注する条件を満たした → 発注せず待機を準備する (待機中・取消した足では何もしない)\\n"\n'
                        '    "                if not skipRef and not na(pQty) and pwState == 0 and not '
                        'pwCancelBar\\n"\n'
                        '    "                    pwState  := 1\\n"\n'
                        '    "                    pwSide   := side\\n"\n'
                        '    "                    pwTrack  := c.track\\n"\n'
