                        '    "                    pwEv     := 1\\n"\n'
                        '    "                    pwNPrep  += 1\\n"\n'
                        '    "            else if not skipRef and not na(pQty)\\n")\n'
                        'SATS_PLOTS = (\n'
                        '    "// XA-7 SATS Pullback の確認表示 (データウィンドウ + 小さな印。永続ラベル・独自アラートは追加しない)\\n"\n'
                        '    "plot(stSats and stSatsShow ? satL1 : na,  \\"SATS · LINE1\\", color = '
