                        '    "plot(stSats and stSatsShow ? satL2 : na,  \\"SATS · LINE2\\", color = '
                        'color.new(color.orange, 0))\\n"\n'
                        '    "plot(stSats and stSatsShow ? satStb : na, \\"SATS · STB\\",   color = '
