                        '    "plot(stSats ? pwState : na,                \\"SATS · 待機中\\",          display = '
                        'display.data_window)\\n"\n'
                        '    "plot(stSats ? pwEv : na,                   \\"SATS · イベント (1 準備 / 2 発注 / -1 期限 / -2 '
                        'Track / -3 資格 / -4 SL0)\\", display = display.data_window)\\n"\n'
                        '    "plot(stSats ? pwLineK : na,                \\"SATS · 対象線 (1 L1 / 2 L2 / 3 STB)\\", '
                        'display = display.data_window)\\n"\n'
                        '    "plot(stSats ? pwLineP : na,                \\"SATS · 対象線の価格 (足 t-1 確定値)\\", display = '
                        'display.data_window)\\n"\n'
                        '    "plot(stSats ? pwP0 : na,                   \\"SATS · P0\\",              display = '
                        'display.data_window)\\n"\n'
                        '    "plot(stSats ? pwSL0 : na,                  \\"SATS · SL0\\",             display = '
                        'display.data_window)\\n"\n'
