                        'location.abovebar, color = color.silver, size = size.tiny)\\n")\n'
                        'STRATEGY_EDITS7 = [\n'
                        '    ("header",\n'
                        '     "//  Strategy: 新しい役割の Zone を Retest 前から候補評価できる (発注は従来どおり Entry A〜D の条件が必要)。\\n",\n'
                        '     "//  Strategy: 新しい役割の Zone を Retest 前から候補評価できる (発注は従来どおり Entry A〜D の条件が必要)。\\n"\n'
                        '     "//  XA-7: Entry Timing (初期 Current = 変更前の発注方式)。SATS Pullback = Entry C '
                        'の発注条件で待機を準備し、次の 5分足以降に\\n"\n'
                        '     "//  SATS 線 (LINE1 / LINE2 / STB、足 t-1 の確定値) への接触と終値での戻りで成行発注。SL0 / TP0 '
                        'は準備時に固定。成績への影響は未確認。\\n"),\n'
                        '    ("input",\n'
                        '     \'stDWait = input.int(30, "D · BOS Wait (confirmed 1M bars)", minval = 1, group = '
                        "G_ST)\\n',\n"
                        '     \'stDWait = input.int(30, "D · BOS Wait (confirmed 1M bars)", minval = 1, group = '
                        "G_ST)\\n' + SATS_INPUTS),\n"
                        '    ("sats", \'bool stShortOK = stDir != "Long Only"\\n\', \'bool stShortOK = stDir != '
                        '"Long Only"\\n\' + SATS_GLOBAL),\n'
                        '    ("sats", "var int    oClosed = 0\\n", "var int    oClosed = 0\\n" + SATS_VARS),\n'
                        '    ("sats", "    if fillNow\\n", SATS_FILL),\n'
                        '    ("sats", "    // (4) 新規 Entry (注文が無く、取消をした足でなく、時間帯の中のときだけ)\\n",\n'
                        '     SATS_WAIT + "    // (4) 新規 Entry (注文が無く、取消をした足でなく、時間帯の中のときだけ)\\n"),\n'
                        '    ("sats", "            if not skipRef and not na(pQty)\\n", SATS_PREP),\n'
                        '    ("sats",\n'
                        '     \'plot(stSessOK ? 1 : 0,                 "ST · Entry Session",     display = '
                        "display.data_window)\\n',\n"
                        '     \'plot(stSessOK ? 1 : 0,                 "ST · Entry Session",     display = '
                        "display.data_window)\\n' + SATS_PLOTS),\n"
                        ']\n'
                        '\n'
                        '\n'
                        '# ---- XA-8: SATS actual RR also for a fill closed within its fill bar (Strategy only; '
                        'after XA-7) -------------------------\n'
                        '#  Record only. f_satRR(side, fill, SL0, TP0) -> [RR, reason] (0 = ok, 1 = risk <= 0: fill '
                        'at / beyond SL0, 2 = TP0 not beyond\n'
                        "#  the fill, 3 = a price is na; RR na unless 0). Holding path (2b'): same order handling, "
                        'the record comes from f_satRR.\n'
                        '#  Closed-in-fill-bar path (filledClosed): SATS Pullback only, the entry price of that '
                        'closed trade with the stored SL0 / TP0;\n'
                        '#  no TP / close order (the trade is already closed). One record per fill (the two paths '
                        'are exclusive branches of (1)):\n'
                        '#  pwNFill counts it, pwFillPath shows the path (1 = holding / 2 = closed in the fill bar). '
                        'Current is unchanged.\n'
                        'SATS_RR_FN = (\n'
                        '    "\\n// XA-8: 実 RR = side × (TP0 − 実約定) ÷ side × (実約定 − SL0)。戻り値 [RR, 理由] (0 = 計算可 / 1 = '
                        '約定が SL0 以遠 (risk <= 0) /\\n"\n'
                        '    "//  2 = TP0 が約定価格の先にない (reward <= 0) / 3 = 価格が na)。理由 0 以外の RR は na\\n"\n'
                        '    "f_satRR(int side, float fillPx, float sl0, float tp0) =>\\n"\n'
                        '    "    float rr  = na\\n"\n'
                        '    "    int   why = 0\\n"\n'
                        '    "    if na(fillPx) or na(sl0) or na(tp0)\\n"\n'
                        '    "        why := 3\\n"\n'
                        '    "    else\\n"\n'
                        '    "        float risk = side * (fillPx - sl0)\\n"\n'
                        '    "        float rew  = side * (tp0 - fillPx)\\n"\n'
                        '    "        if risk <= 0\\n"\n'
                        '    "            why := 1\\n"\n'
                        '    "        else if rew <= 0\\n"\n'
                        '    "            why := 2\\n"\n'
                        '    "        else\\n"\n'
                        '    "            rr := rew / risk\\n"\n'
                        '    "    [rr, why]\\n")\n'
                        'STRATEGY_EDITS8 = [\n'
                        '    ("header",\n'
                        '     "//  SATS 線 (LINE1 / LINE2 / STB、足 t-1 の確定値) への接触と終値での戻りで成行発注。SL0 / TP0 '
                        'は準備時に固定。成績への影響は未確認。\\n",\n'
                        '     "//  SATS 線 (LINE1 / LINE2 / STB、足 t-1 の確定値) への接触と終値での戻りで成行発注。SL0 / TP0 '
                        'は準備時に固定。成績への影響は未確認。\\n"\n'
                        '     "//  XA-8: SATS の実 RR を約定足内で SL 決済まで終わった約定でも記録 (closed trade の実約定価格 + SL0 / '
                        'TP0。注文は出さない)。\\n"),\n'
                        '    ("rr", "    [bk, bp]\\n", "    [bk, bp]\\n" + SATS_RR_FN),\n'
                        '    ("rr", "var int   pwNBad   = 0\\n",\n'
                        '     "var int   pwNBad   = 0\\n"\n'
                        '     "var int   pwRRWhy  = na      // XA-8: 実 RR の理由 (0 計算可 / 1 risk <= 0 / 2 reward <= 0 / '
                        '3 na)\\n"\n'
                        '     "var int   pwNFill  = 0       // XA-8: 実 RR を記録した SATS 約定の件数 (1 約定 1 回)\\n"\n'
                        '     "var int   pwFillPath = 0     // XA-8: 直近の記録経路 (1 = 約定後も保有中 / 2 = 約定足内で決済済み)\\n"),\n'
                        '    ("rr",\n'
                        '     "            // 約定した足の中で SL まで成立した\\n            map.put(stUsed, oTrack, '
                        'true)\\n            oState := 0\\n",\n'
                        '     "            // 約定した足の中で SL まで成立した\\n            map.put(stUsed, oTrack, '
                        'true)\\n            oState := 0\\n"\n'
                        '     "            if stSats     // XA-8: 決済済みの SATS 約定も実 RR を記録する (TP / 決済の注文は出さない)\\n"\n'
                        '     "                [rrC, whyC] = f_satRR(oSide, strategy.closedtrades.entry_price(ct - '
                        '1), oSL, oTP0)\\n"\n'
                        '     "                pwRRFill   := rrC\\n"\n'
                        '     "                pwRRWhy    := whyC\\n"\n'
                        '     "                pwNFill    += 1\\n"\n'
                        '     "                pwFillPath := 2\\n"),\n'
                        '    ("rr", "        pwRRFill := riskS > 0 ? rewS / riskS : na\\n",\n'
                        '     "        [rrH, whyH] = f_satRR(oSide, oFill, oSL, oTP0)     // XA-8: 記録だけ '
                        '(下の注文処理は従来どおり)\\n"\n'
                        '     "        pwRRFill   := rrH\\n"\n'
                        '     "        pwRRWhy    := whyH\\n"\n'
                        '     "        pwNFill    += 1\\n"\n'
                        '     "        pwFillPath := 1\\n"),\n'
                        '    ("rr", "                    pwRRFill := na\\n", "                    pwRRFill := '
                        'na\\n                    pwRRWhy  := na\\n"),\n'
                        '    ("rr",\n'
                        '     \'plot(stSats ? pwRRFill : na,               "SATS · 実 RR (実約定価格)", display = '
                        "display.data_window)\\n',\n"
                        '     \'plot(stSats ? pwRRFill : na,               "SATS · 実 RR (実約定価格)", display = '
                        "display.data_window)\\n'\n"
                        '     \'plot(stSats ? pwRRWhy : na,                "SATS · 実 RR の理由 (0 可 / 1 risk<=0 / 2 '
                        'reward<=0 / 3 na)", display = display.data_window)\\n\'\n'
                        '     \'plot(stSats ? pwNFill : na,                "SATS · 実 RR 記録件数", display = '
                        "display.data_window)\\n'\n"
                        '     \'plot(stSats ? pwFillPath : na,             "SATS · 記録経路 (1 保有中 / 2 約定足内で決済済み)", '
                        "display = display.data_window)\\n'),\n"
                        ']\n'
                        '\n'
                        '\n'
                        '# ---- XA-9: SATS Pullback — no zone re-check after the prep; touch recorded, rebound on '
                        'the touch bar or later (after XA-8) ---\n'
                        '#  SATS Pullback only (Current unchanged). Cancels: the wall-clock limit and SL0 only '
                        '(before any rebound); the Track /\n'
                        '#  Strong-candidate re-checks of XA-7 are removed. Before the touch the line is re-picked '
                        'every bar (t-1 lines, previous close,\n'
                        '#  SL0 < L < P0 and beyond the previous close, ties L1 -> L2 -> STB); a touch (low <= L <= '
                        'high, L in range) records the line\n'
                        '#  kind. After the touch that kind is kept (its t-1 value every bar, no "beyond the '
                        'previous close" requirement; na / out of\n'
                        '#  range -> no order but the record stays). Rebound A: touch and close back on the bar; B: '
                        'touched before, previous close at or\n'
                        '#  beyond L and close back beyond L (both against the same L). Plus SL0 < close < P0 '
                        '(mirrored), session, no order, valid qty.\n'
                        '#  The touch state is reset on prep / cancel / order. strip_strategy9() -> the Strategy of '
                        'a32bd85.\n'
                        'SATS_WAIT8 = SATS_WAIT.replace("                    pwRRFill := na\\n", '
                        '"                    pwRRFill := na\\n                    pwRRWhy  := na\\n")\n'
                        'SATS_WAIT9 = (\n'
                        '    "    // (3b) XA-7 / XA-9 SATS Pullback の待機判定 (準備足の次の足から)。取消を反発より優先する\\n"\n'
                        '    "    //   取消 (XA-9): 期限 (準備足の終了時刻からの実時間) / 固定 SL0 到達 だけ。元 Zone の Strong 資格・Track の存続 / '
                        '一致・候補一覧\\n"\n'
                        '    "    //   からの脱落では取り消さない (保存した方向 / P0 / SL0 / TP0 を使い続ける)。取消だけでは使用済み Track にしない\\n"\n'
                        '    "    //   接触前: 毎足、足 t-1 の確定線と前足終値から最寄りの適格線を選び直す。low <= L <= high で接触 → 線の種類を記録\\n"\n'
                        '    "    //   接触後: 記録した種類の線の足 t-1 確定値を毎足使う (別の線へ選び替えない。前足終値との位置関係は再要求しない)。\\n"\n'
                        '    "    //           na / SL0〜P0 の範囲外の足は発注しないが、接触記録は消さない\\n"\n'
                        '    "    //   反発: A = その足で接触して終値が戻る / B = 接触済みで、前足終値 <= L (Short は >=) かつ当足終値 > L (Short は '
                        '<)\\n"\n'
                        '    "    bool  pwCancelBar = false\\n"\n'
                        '    "    if stSats and pwState == 1 and bar_index > pwBar\\n"\n'
                        '    "        int why = 0\\n"\n'
                        '    "        if time_close - pwEndT >= stSatsWait * 60000\\n"\n'
                        '    "            why := -1\\n"\n'
                        '    "        else if pwSide == 1 ? low <= pwSL0 : high >= pwSL0\\n"\n'
                        '    "            why := -4\\n"\n'
                        '    "        if why != 0\\n"\n'
                        '    "            pwState     := 0\\n"\n'
                        '    "            pwCancelBar := true\\n"\n'
                        '    "            pwEv        := why\\n"\n'
                        '    "            pwNExp  += why == -1 ? 1 : 0\\n"\n'
                        '    "            pwNSL   += why == -4 ? 1 : 0\\n"\n'
                        '    "            pwTouched  := false\\n"\n'
                        '    "            pwTouchK   := 0\\n"\n'
                        '    "            pwTouchBar := na\\n"\n'
                        '    "        else\\n"\n'
                        '    "            int   lk = 0\\n"\n'
                        '    "            float lp = na\\n"\n'
                        '    "            if not pwTouched\\n"\n'
                        '    "                [k0, v0] = f_satPick(pwSide, pwP0, pwSL0, close[1], satL1[1], '
                        'satL2[1], satStb[1])\\n"\n'
                        '    "                lk := k0\\n"\n'
                        '    "                lp := v0\\n"\n'
                        '    "            else\\n"\n'
                        '    "                lk := pwTouchK\\n"\n'
                        '    "                lp := pwTouchK == 1 ? satL1[1] : pwTouchK == 2 ? satL2[1] : '
                        'satStb[1]\\n"\n'
                        '    "            pwLineK := lk\\n"\n'
                        '    "            pwLineP := lp\\n"\n'
                        '    "            bool inRange  = lk != 0 and not na(lp) and (pwSide == 1 ? (lp > pwSL0 and '
                        'lp < pwP0) : (lp < pwSL0 and lp > pwP0))\\n"\n'
                        '    "            bool touchNow = inRange and low <= lp and lp <= high\\n"\n'
                        '    "            bool rebA     = touchNow and (pwSide == 1 ? close > lp : close < lp)\\n"\n'
                        '    "            bool rebB     = pwTouched and inRange and (pwSide == 1 ? (close[1] <= lp '
                        'and close > lp) : (close[1] >= lp and close < lp))\\n"\n'
                        '    "            if touchNow and not pwTouched\\n"\n'
                        '    "                pwTouched    := true\\n"\n'
                        '    "                pwTouchK     := lk\\n"\n'
                        '    "                pwTouchBar   := bar_index\\n"\n'
                        '    "                pwNTouchPrep += 1\\n"\n'
                        '    "            bool priceOK = pwSide == 1 ? (close > pwSL0 and close < pwP0) : (close < '
                        'pwSL0 and close > pwP0)\\n"\n'
                        '    "            if (rebA or rebB) and priceOK and stSessOK and oState == 0\\n"\n'
                        '    "                float q = f_stQty(pwSide, close, pwSL0)\\n"\n'
                        '    "                if not na(q)\\n"\n'
                        '    "                    oSeq    += 1\\n"\n'
                        '    "                    oEid    := (pwSide == 1 ? \\"L\\" : \\"S\\") + '
                        'str.tostring(oSeq)\\n"\n'
                        '    "                    oXid    := oEid + \\" SL/TP\\"\\n"\n'
                        '    "                    oSide   := pwSide\\n"\n'
                        '    "                    oTrack  := pwTrack\\n"\n'
                        '    "                    oLimit  := false\\n"\n'
                        '    "                    oL      := na\\n"\n'
                        '    "                    oSL     := pwSL0\\n"\n'
                        '    "                    oStop   := pwSL0\\n"\n'
                        '    "                    oTP     := na\\n"\n'
                        '    "                    oTP0    := pwTP0\\n"\n'
                        '    "                    oFill   := na\\n"\n'
                        '    "                    oBE     := false\\n"\n'
                        '    "                    oClosed := strategy.closedtrades\\n"\n'
                        '    "                    oState  := 1\\n"\n'
                        '    "                    strategy.entry(oEid, pwSide == 1 ? strategy.long : strategy.short, '
                        'qty = q)\\n"\n'
                        '    "                    strategy.exit(oXid, oEid, stop = oSL)\\n"\n'
                        '    "                    pwRRPlan := pwSide * (pwTP0 - close) / (pwSide * (close - '
                        'pwSL0))\\n"\n'
                        '    "                    pwRRFill := na\\n"\n'
                        '    "                    pwRRWhy  := na\\n"\n'
                        '    "                    pwState  := 0\\n"\n'
                        '    "                    pwEv     := 2\\n"\n'
                        '    "                    pwNOrder += 1\\n"\n'
                        '    "                    pwNOrdSame  += rebA ? 1 : 0\\n"\n'
                        '    "                    pwNOrdLater += rebA ? 0 : 1\\n"\n'
                        '    "                    pwTouched  := false\\n"\n'
                        '    "                    pwTouchK   := 0\\n"\n'
