                        '\n'
                        '# ---- XA-10: SATS Pullback with Entry Mode A / B / C / D (Strategy only; after XA-9) '
                        '-------------------------------------\n'
                        '#  The prep already sits in the shared order block (4) of every mode: it runs exactly where '
                        'Current places the order, with\n'
                        "#  that mode's ref (A: the limit price pL / B, C, D: the confirmed close), pSL, tpRef and "
                        'pQty; D reaches it only through dSrc\n'
                        '#  (after its 1M BOS). XA-10 removes the "Entry C only" runtime.error and updates the '
                        'tooltip / header / comment. No logic\n'
                        '#  line changes (SATS + C is the same code path). strip_strategy10() -> the Strategy of '
                        '3ca1837.\n'
                        'STRATEGY_EDITS10 = [\n'
                        '    ("header",\n'
                        '     "//  接触足で戻る場合 (A) と、接触後の別の足で前足終値 → 当足終値が同じ線 L を越えて戻る場合 (B) を反発とする。成績への影響は未確認。\\n",\n'
                        '     "//  接触足で戻る場合 (A) と、接触後の別の足で前足終値 → 当足終値が同じ線 L を越えて戻る場合 (B) を反発とする。成績への影響は未確認。\\n"\n'
                        '     "//  XA-10: SATS Pullback を Entry Mode A〜D すべてで使える '
                        '(各モードの既存の発注条件が成立した足で、注文の代わりに待機を準備。\\n"\n'
                        '     "//  P0 = A は元の指値価格 pL (指値注文は出さない) / B・C・D はその確定足の終値。D は既存の 1分足 BOS '
                        '確認後)。待機・反発・取消は共通。\\n"),\n'
                        '    ("text",\n'
                        '     \'     "SATS Pullback: Entry C が発注する条件を満たした足で発注せず待機を始め、次の 5分足以降に SATS 線 (LINE1 / LINE2 '
