                        '     \'     "(LINE1 / LINE2 / STB) への\\\\n" +\\n\'),\n'
                        '    ("text",\n'
                        '     \'     "Entry C 専用: 他の Entry Mode と組み合わせると停止して表示する (黙って別動作にしない)。")\\n\',\n'
                        '     \'     "P0: A は元の指値価格 (指値注文は出さない) / B・C・D はその確定足の終値。D は既存の 1分足 BOS '
                        '確認後に待機を始める。")\\n\'),\n'
                        '    ("gate",\n'
                        "     'if stSats and not stModeC\\n'\n"
                        '     \'    runtime.error("Entry Timing = SATS Pullback は Entry Mode C: Candle Pattern 専用です '
                        '(他の Entry Mode は対象外)。")\\n\',\n'
                        "     '//  XA-10: SATS Pullback は Entry Mode A〜D すべてで使える (C 専用の停止は廃止)。\\n'),\n"
                        '    ("text",\n'
                        '     "                // XA-7: Entry C が発注する条件を満たした → 発注せず待機を準備する (待機中・取消した足では何もしない)\\n",\n'
                        '     "                // XA-7 / XA-10: 選択した Entry Mode (A〜D) が発注する条件を満たした → '
                        '発注せず待機を準備する\\n"\n'
                        '     "                //   (P0 = ref: A は指値価格 pL / B・C・D は確定足の終値。待機中・取消した足では何もしない)\\n"),\n'
                        ']\n'
                        '\n'
                        '\n'
                        '# ---- XA-11: SATS comparison switches (Strategy only; after XA-10) '
                        '-------------------------------------------------------\n'
                        '#  Two independent inputs, both default OFF (both OFF = the XA-10 code path): (1) the bar '
                        'that places the SATS order must\n'
                        '#  itself be bullish (Long close > open) / bearish (Short close < open), on top of rebound '
                        'A or B of that same bar (no stored\n'
                        '#  rebound; the wait and the touch record stay when it fails); (2) a near approach to the '
                        't-1 line L counts as a touch\n'
                        '#  (Short: high < L and L - high <= D / Long: low > L and low - L <= D, D in USD, default '
                        '3.0, 0 = real touch only); the\n'
                        '#  close-back test keeps the original L and the SL0..P0 window is kept. strip_strategy11() '
                        '-> the Strategy of ae2c2e8.\n'
                        'STRATEGY_EDITS11 = [\n'
                        '    ("header",\n'
                        '     "//  P0 = A は元の指値価格 pL (指値注文は出さない) / B・C・D はその確定足の終値。D は既存の 1分足 BOS '
                        '確認後)。待機・反発・取消は共通。\\n",\n'
                        '     "//  P0 = A は元の指値価格 pL (指値注文は出さない) / B・C・D はその確定足の終値。D は既存の 1分足 BOS '
                        '確認後)。待機・反発・取消は共通。\\n"\n'
                        '     "//  XA-11: SATS の比較用設定 2 つ (独立・初期 OFF、両方 OFF は XA-10 と同じ)。① 発注する足自身の陽線 / 陰線を反発 A・B '
                        'に追加で要求。\\n"\n'
                        '     "//  ② 線 L の手前 (許容距離 $ 以内) までの接近も接触扱い (終値の戻りは元の L で判定)。成績への影響は未確認。\\n"),\n'
                        '    ("input",\n'
                        '     \'stSatsShow = input.bool(true, "SATS · 線を表示", group = G_STW)\\n\',\n'
                        '     \'stSatsShow = input.bool(true, "SATS · 線を表示", group = G_STW)\\n\'\n'
