                        '     \'     tooltip = "XA-11 比較用 (初期 OFF)。ON: 発注を判断する 5分足自身が Long は close > open / Short は '
                        'close < open (同値足は不成立)。\\\\n" +\\n\'\n'
                        '     \'     "その足で既存の反発 A または B と同時に成立したときだけ発注する。不成立でも待機と接触記録は残す (過去の反発は保存しない)。")\\n\'\n'
                        '     \'stSatsNear = input.bool(false, "SATS · 近接を接触扱い", group = G_STW,\\n\'\n'
                        '     \'     tooltip = "XA-11 比較用 (初期 OFF)。ON: 実接触 (low <= L <= high) に加え、線 L (足 t-1 の確定値) '
                        'の手前までの接近も接触とする。\\\\n" +\\n\'\n'
                        '     \'     "Short: high < L かつ L − high <= 許容距離 / Long: low > L かつ low − L <= '
                        '許容距離。終値の戻りは元の線 L で判定する。")\\n\'\n'
                        '     \'stSatsNearD = input.float(3.0, "SATS · 近接許容距離 ($)", minval = 0.0, step = 0.5, group '
                        "= G_STW,\\n'\n"
                        '     \'     tooltip = "XAUUSD の価格差 (ドル)。ATR・pips・終値と線の距離ではない。0 なら実接触だけと同じ。")\\n\'),\n'
                        '    ("text",\n'
                        '     "var int   pwNOrdSame   = 0     // XA-9: 同じ足の接触・反発 (A) で発注した件数\\n",\n'
                        '     "var int   pwNOrdSame   = 0     // XA-9: 同じ足の接触・反発 (A) で発注した件数 (XA-11: 近接 ON '
                        'では近接を接触扱いにした同一足反発を含む)\\n"),\n'
                        '    ("text",\n'
                        '     "    //   反発: A = その足で接触して終値が戻る / B = 接触済みで、前足終値 <= L (Short は >=) かつ当足終値 > L (Short は '
                        '<)\\n",\n'
                        '     "    //   反発: A = その足で接触して終値が戻る / B = 接触済みで、前足終値 <= L (Short は >=) かつ当足終値 > L (Short は '
                        '<)\\n"\n'
                        '     "    //   XA-11 ② (近接 ON): 接触 = 実接触 または 線の手前までの接近 (Long low > L かつ low − L <= 許容距離 / '
                        'Short high < L かつ\\n"\n'
                        '     "    //           L − high <= 許容距離)。接触記録・線の固定・反発 A / B は同じ処理を共用し、終値の基準は元の L のまま\\n"\n'
                        '     "    //   XA-11 ① (陽線 / 陰線 ON): 発注する足自身が Long close > open / Short close < open。同じ足の A '
                        'または B と同時に必要。\\n"\n'
                        '     "    //           不成立でも待機・接触記録は残す (接触の記録自体は制限しない)\\n"),\n'
                        '    ("near",\n'
                        '     "            bool touchNow = inRange and low <= lp and lp <= high\\n",\n'
                        '     "            bool touchHit  = inRange and low <= lp and lp <= high\\n"\n'
                        '     "            bool touchNear = stSatsNear and inRange and (pwSide == 1 ? (low > lp and '
                        'low - lp <= stSatsNearD) : (high < lp and lp - high <= stSatsNearD))\\n"\n'
                        '     "            bool touchNow  = touchHit or touchNear\\n"),\n'
                        '    ("body",\n'
