                        "display.data_window)\\n',\n"
                        '     \'plot(stSats ? pwNOrdSame : na,             "SATS · 発注 (同じ足の接触・反発。近接 ON '
                        'は近接の同一足反発を含む)", display = display.data_window)\\n\'),\n'
