                        '\n'
                        '\n'
                        '# ---- XA-13: SATS all-selected-timeframes opposite-band filter (Strategy only; after '
                        'XA-12) ------------------------------\n'
                        '#  Five independent inputs (D / 4H / 1H / 15m / 5m, all default OFF = no filter = the XA-12 '
                        'path). At the final SATS order\n'
                        '#  test (after rebound A / B, body, price window, session, qty) the order is skipped only '
                        'when at least one timeframe is\n'
                        '#  selected and every selected one shows the opposite band (Short: all blue = 1 / Long: all '
                        'red = -1); 0, the own colour or\n'
                        "#  na (not computed yet) on any selected timeframe -> no skip. Bands = f_satBand's stateV "
                        '(close vs LINE1 / LINE2 / STB),\n'
                        "#  computed on each timeframe's own history (D / 240 / 60 / 15: f_satTfState()[1]-style "
                        'value of the last confirmed bar via\n'
                        '#  request.security + lookahead_on, called unconditionally at global scope); 5m = the '
                        'existing satBand of the order bar.\n'
                        '#  A skip changes nothing (wait, touch record, line kind, P0 / SL0 / TP0, prep time, '
