                        '    ("header",\n'
                        '     "//  年別の検証は未確認)。初期状態では Short は 4H・1H が両方青、Long は両方赤のときだけ見送る。判定・計算・他の設定は変えない。\\n",\n'
                        '     "//  年別の検証は未確認)。初期状態では Short は 4H・1H が両方青、Long は両方赤のときだけ見送る。判定・計算・他の設定は変えない。\\n"\n'
                        '     "//  XA-15: 建値移動の Trigger 方式 (比較用。初期 Fixed Distance 15 USD = 従来どおり)。Risk Multiple = '
                        '実約定価格から初期 SL までの\\n"\n'
                        '     "//  距離 × R / TP Progress = 実約定価格から実際の TP までの距離 × 比率。判断・注文更新は従来の確定 5分足の建値処理のまま。\\n"),\n'
                        '    ("input",\n'
                        '     \'stBEDist = input.float(15.0, "Breakeven Trigger ($)", minval = 0.0, step = 0.5, '
                        "group = G_STT)\\n',\n"
                        '     \'stBEDist = input.float(15.0, "Breakeven Trigger ($)", minval = 0.0, step = 0.5, '
