                        '     \'     "Risk Multiple: 1R = 実約定価格から初期 SL までの距離。含み益が 1R × 倍率に届いたら建値へ。\\\\n" +\\n\'\n'
                        '     \'     "TP Progress: 実約定価格から実際に設定した TP までの距離 × 比率 (0.5TP = TP までの半分進んだ)。TP 価格や TP '
