                        '     \'     "RR 方式 / TP 比率方式でも判断・注文更新は従来の確定 5分足処理 (Long は high / Short は '
                        'low、等値で成立、次の足から有効)。")\\n\'\n'
                        '     \'stBER = input.float(1.0, "Breakeven Trigger (R)", minval = 0.1, step = 0.1, group = '
                        "G_STT)\\n'\n"
                        '     \'stBETp = input.float(0.5, "Breakeven Trigger (TP Ratio)", minval = 0.05, maxval = '
                        "1.0, step = 0.05, group = G_STT)\\n'),\n"
                        '    ("trigger",\n'
                        '     "    [skip, tp]\\n\\nvar array<StCand>  stPrev = array.new<StCand>()\\n",\n'
                        '     "    [skip, tp]\\n"\n'
                        '     "\\n"\n'
                        '     "// XA-15: 建値移動に必要な含み益幅。Fixed Distance = stBEDist (従来どおり、距離検査を追加しない) / Risk Multiple = '
                        '初期リスク距離\\n"\n'
                        '     "//  side × (実約定価格 − 初期 SL) × R / TP Progress = side × (TP − 実約定価格) × 比率。新方式は基準距離が na '
                        '/ 0 以下なら na (移動しない)\\n"\n'
                        '     "f_beTrig(int side, float fillPx, float sl, float tp) =>\\n"\n'
                        '     "    float r  = side * (fillPx - sl)\\n"\n'
                        '     "    float tg = side * (tp - fillPx)\\n"\n'
                        '     \'    stBEMode == "Risk Multiple" ? (not na(r) and r > 0 ? r * stBER : na) :\\n\'\n'
                        '     \'     stBEMode == "TP Progress" ? (not na(tg) and tg > 0 ? tg * stBETp : na) : '
                        "stBEDist\\n'\n"
                        '     "\\n"\n'
                        '     "var array<StCand>  stPrev = array.new<StCand>()\\n"),\n'
                        '    ("trigger",\n'
