                        '     "    // (2c) 建値移動: この確定足で含み益が Trigger に届いたら stop を約定価格へ (次の足から有効)\\n"\n'
                        '     "    //   XA-15: Trigger 幅は選択した方式 (約定確認時の oFill / 初期 oSL / 設定した oTP から。oStop は使わない)。na '
