                        '\n'
                        '\n'
                        '# ---- XA-16: SATS immediate entry on a recent SATS rebound (Strategy only; after XA-15) '
                        '---------------------------------\n'
                        "#  Two inputs (default OFF / 1). An independent rebound history (never the wait's pw* "
                        'state): every bar, per side and per\n'
                        "#  line (LINE1 / LINE2 / STB), with that line's bar e-1 value L: touch = low <= L <= high "
                        'or (near ON) the near approach;\n'
                        '#  A = touch with the previous close on the trade side and the close back on the trade '
                        'side; B = an earlier touch of the\n'
                        '#  same line (record) and close[1] / close across the same L; a valid rebound also needs '
                        'the body (when ON) on bar e and\n'
                        '#  consumes the record. Latest rebound bar per side, same-bar priority LINE1 -> LINE2 -> '
                        'STB. At the SATS prep point\n'
                        "#  (stSats, prep conditions, no wait, not a cancel bar): ON + 0 <= t - e <= N + this bar's "
                        'filter / qty f_stQty(side,\n'
                        '#  close, SL0) / SL-TP side -> market order (path 2, TP0 / RR / fill handled by the SATS '
                        'path); otherwise the usual prep.\n'
                        '#  strip_strategy16() -> the Strategy of b59d621 (= e2cf617 + XA-15).\n'
                        'STRATEGY_EDITS16 = [\n'
                        '    ("header",\n'
                        '     "//  距離 × R / TP Progress = 実約定価格から実際の TP までの距離 × 比率。判断・注文更新は従来の確定 5分足の建値処理のまま。\\n",\n'
                        '     "//  距離 × R / TP Progress = 実約定価格から実際の TP までの距離 × 比率。判断・注文更新は従来の確定 5分足の建値処理のまま。\\n"\n'
                        '     "//  XA-16: SATS 直近反発の即時エントリー (比較用・初期 OFF / 有効本数 1)。各 Entry Mode の待機準備地点で、同方向の SATS '
                        '反発が\\n"\n'
                        '     "//  0 <= t − e <= N 本以内に成立済みなら引きつけずにその確定足で成行 (P0 / SL0 / TP0 '
                        'は準備時と同じ)。なければ従来どおり待機。\\n"),\n'
                        '    ("input",\n'
                        '     \'     tooltip = "5分足は発注を判断するその 5分足の確定時点の SATS バンド (この Strategy の SATS '
