                        '     \'stSatsNow = input.bool(false, "SATS · 直近の反発で即時エントリー", group = G_STW,\\n\'\n'
                        '     \'     tooltip = "XA-16 比較用 (初期 OFF)。SATS Pullback の待機を準備する足 t で、同方向の SATS 反発 (A / B '
