                        '     \'     "この足の時間帯・逆方向一致・注文なし・数量 (終値と SL0)・SL / TP の向きが必要。成立しなければ従来どおり待機を始める。")\\n\'\n'
                        '     \'stSatsNowN = input.int(1, "SATS · 直近反発の有効本数（5分足）", minval = 0, step = 1, group = '
                        "G_STW,\\n'\n"
                        '     \'     tooltip = "0 = シグナル確定足の反発だけ / 1 = その足と直前 1 本 / 3 = 直前 3 本まで (境界を含む。実時間ではなく '
                        '5分足の本数。\\\\n" +\\n\'\n'
                        '     \'     "B は接触足ではなく反発が成立した足から数える)。")\\n\'),\n'
                        '    ("hist",\n'
                        '     "bool satSkipL = f_satAllAgainst(-1)     // Long を見送る: 選択した時間足がすべて赤\\n",\n'
                        '     "bool satSkipL = f_satAllAgainst(-1)     // Long を見送る: 選択した時間足がすべて赤\\n"\n'
                        '     "\\n"\n'
                        '     "// XA-16: 準備前の SATS 反発の履歴 (待機 pw* とは独立。毎足・無条件に更新)。足 e の判定には足 e-1 で確定した線 L だけを使う。\\n"\n'
                        '     "//  方向 side × 線 (LINE1 / LINE2 / STB) ごとに: 接触 = low <= L <= high、近接 ON なら Long low > '
                        'L かつ low − L <= 許容距離 /\\n"\n'
                        '     "//  Short high < L かつ L − high <= 許容距離。A = 接触 + 前足終値が取引方向側 (Long close[1] > L / Short '
                        'close[1] < L) + 終値が\\n"\n'
                        '     "//  取引方向側 (Long close > L / Short close < L)。B = 同じ線への先行接触の記録 + close[1] <= L < close '
                        '(Short は close[1] >= L > close)。\\n"\n'
                        '     "//  陽線陰線 ON なら反発足 e 自身が Long close > open / Short close < '
                        'open。有効な反発はその線の接触記録を消費する\\n"\n'
                        '     "//  (反発しなかった接触は記録を残す)。戻り値 [反発成立, 次の記録]。SATS の青 / 赤、P0 / SL0、Zone 資格は使わない\\n"\n'
                        '     "f_satHist(int side, float L, bool rec) =>\\n"\n'
