                        '    ("state",\n'
                        '     "var float oTP0     = na      // SATS で発注した注文の TP0 (約定確認時の TP)\\n",\n'
                        '     "var float oTP0     = na      // SATS で発注した注文の TP0 (約定確認時の TP)\\n"\n'
                        '     "var int   oPath    = 0       // XA-16: 直近の SATS 発注の経路 (1 = 引きつけ / 2 = 即時)\\n"\n'
                        '     "var int   pwNNow   = 0       // XA-16: 即時エントリーの発注件数\\n"\n'
                        '     "var int   pwNowK   = 0       // XA-16: 即時エントリーで採用した反発の線 (1 LINE1 / 2 LINE2 / 3 '
                        'STB)\\n"\n'
                        '     "var int   pwNowAge = na      // XA-16: その反発からの経過本数 (t − e)\\n"),\n'
                        '    ("path",\n'
                        '     "                    oTP0    := pwTP0\\n",\n'
                        '     "                    oTP0    := pwTP0\\n"\n'
                        '     "                    oPath   := 1\\n"),\n'
                        '    ("now",\n'
                        '     "                if not skipRef and not na(pQty) and pwState == 0 and not '
                        'pwCancelBar\\n",\n'
                        '     "                // XA-16: 直近の反発で即時エントリー (ON のときだけ。待機中・取消した足では判定しない = 割り込みなし)\\n"\n'
                        '     "                //   有効 = 0 <= t − e <= N (e = 同方向の最新の反発成立足)。この足の逆方向一致・数量 '
                        'f_stQty(side, close, SL0)・\\n"\n'
                        '     "                //   SL / TP の向き (SL0 と TP0 の間に終値) が必要。過去の反発線の SL0〜P0 範囲・P0 '
                        'より有利な終値・\\n"\n'
                        '     "                //   この足の再接触 / 実体は要求しない。成立しなければ下の従来の準備 (接触待ちから) へ進む\\n"\n'
                        '     "                bool nowGo = false\\n"\n'
                        '     "                if stSatsNow and not skipRef and not na(pQty) and pwState == 0 and '
                        'not pwCancelBar\\n"\n'
                        '     "                    int   hBar = side == 1 ? hRebBarL : hRebBarS\\n"\n'
                        '     "                    int   hAge = na(hBar) ? na : bar_index - hBar\\n"\n'
                        '     "                    float nQty = f_stQty(side, close, pSL)\\n"\n'
                        '     "                    bool  nMtf = not (side == 1 ? satSkipL : satSkipS)\\n"\n'
                        '     "                    bool  nDir = side * (close - pSL) > 0 and side * (tpRef - close) '
                        '> 0\\n"\n'
                        '     "                    if not na(hAge) and hAge >= 0 and hAge <= stSatsNowN and nMtf and '
                        'nDir and not na(nQty)\\n"\n'
                        '     "                        oSeq    += 1\\n"\n'
                        '     "                        oEid    := (side == 1 ? \\"L\\" : \\"S\\") + '
                        'str.tostring(oSeq)\\n"\n'
