                        '     "                        oSide   := side\\n"\n'
                        '     "                        oTrack  := c.track\\n"\n'
                        '     "                        oLimit  := false\\n"\n'
                        '     "                        oL      := na\\n"\n'
                        '     "                        oSL     := pSL\\n"\n'
                        '     "                        oStop   := pSL\\n"\n'
                        '     "                        oTP     := na\\n"\n'
                        '     "                        oTP0    := tpRef\\n"\n'
                        '     "                        oFill   := na\\n"\n'
                        '     "                        oBE     := false\\n"\n'
                        '     "                        oClosed := strategy.closedtrades\\n"\n'
                        '     "                        oState  := 1\\n"\n'
                        '     "                        oPath   := 2\\n"\n'
                        '     "                        strategy.entry(oEid, side == 1 ? strategy.long : '
                        'strategy.short, qty = nQty)\\n"\n'
