                        '     "                        pwRRPlan := side * (tpRef - close) / (side * (close - '
                        'pSL))\\n"\n'
                        '     "                        pwRRFill := na\\n"\n'
                        '     "                        pwRRWhy  := na\\n"\n'
                        '     "                        pwEv     := 3\\n"\n'
                        '     "                        pwNNow   += 1\\n"\n'
                        '     "                        pwNowK   := side == 1 ? hRebKL : hRebKS\\n"\n'
                        '     "                        pwNowAge := hAge\\n"\n'
                        '     "                        nowGo    := true\\n"\n'
                        '     "                if not skipRef and not na(pQty) and pwState == 0 and not pwCancelBar '
                        'and not nowGo\\n"),\n'
                        '    ("plot",\n'
                        '     \'plot(stSats ? pwNBad : na,                 "SATS · 不適切な約定の決済件数", display = '
                        "display.data_window)\\n',\n"
                        '     \'plot(stSats ? pwNBad : na,                 "SATS · 不適切な約定の決済件数", display = '
                        "display.data_window)\\n'\n"
                        '     \'plot(stSats ? oPath : na,                  "SATS · 直近発注の経路 (1 引きつけ / 2 即時)", display '
                        "= display.data_window)\\n'\n"
                        '     \'plot(stSats ? pwNNow : na,                 "SATS · 即時エントリーの発注件数 (引きつけは「発注件数」)", '
                        "display = display.data_window)\\n'\n"
                        '     \'plot(stSats ? pwNowK : na,                 "SATS · 即時で採用した反発の線 (1 L1 / 2 L2 / 3 '
                        'STB)", display = display.data_window)\\n\'\n'
                        '     \'plot(stSats ? pwNowAge : na,               "SATS · 即時で採用した反発からの本数 (t − e)", display '
                        "= display.data_window)\\n'\n"
                        '     \'plot(stSats and oPath == 1 ? pwRRPlan : na, "SATS · 引きつけ 予定 RR", display = '
