                        "display.data_window)\\n'\n"
                        '     \'plot(stSats and oPath == 2 ? pwRRPlan : na, "SATS · 即時 予定 RR", display = '
                        "display.data_window)\\n'\n"
                        '     \'plot(stSats and oPath == 2 ? pwRRFill : na, "SATS · 即時 実 RR", display = '
                        "display.data_window)\\n'\n"
