                        "display.data_window)\\n'),\n"
                        '    ("plot",\n'
                        '     \'plotshape(stSats and pwEv == 2, "SATS · 発注", style = shape.triangledown, location = '
                        "location.abovebar, color = color.red, size = size.tiny)\\n',\n"
                        '     \'plotshape(stSats and pwEv == 2, "SATS · 発注", style = shape.triangledown, location = '
                        "location.abovebar, color = color.red, size = size.tiny)\\n'\n"
                        '     \'plotshape(stSats and pwEv == 3, "SATS · 即時発注", style = shape.diamond, location = '
                        "location.abovebar, color = color.blue, size = size.tiny)\\n'),\n"
                        ']\n'
                        '\n'
                        '\n'
                        '# ---- XA-17: contact-based valid bars for both SATS paths (Strategy only; after XA-16) '
                        '----------------------------------\n'
                        '#  Immediate side: the history keeps the contact bar q per side / line (A: the rebound bar '
                        'itself, B: the recorded touch, never\n'
                        '#  moved to the rebound bar; a record older than N is dropped before the test, so a new '
                        'touch can start a new one) and a list\n'
                        '#  of rebounds (q, e, line); at the prep point the latest e among 0 <= t - q <= N (same e: '
                        'LINE1 -> LINE2 -> STB) is used —\n'
                        '#  the XA-16 "t - e <= N" latest-rebound state is removed. Pull side (new switch, default '
                        'OFF = XA-16 path): while waiting,\n'
                        '#  a held touch with t - q > N is released (record + held line) before the line choice, the '
                        'wait / its prep time / the overall\n'
                        '#  expiry stay; no auto-extension on re-touch. strip_strategy17() -> the Strategy of '
                        '4c56095.\n'
                        "HIST17_OLD = '// XA-16: 準備前の SATS 反発の履歴 (待機 pw* とは独立。毎足・無条件に更新)。足 e の判定には足 e-1 で確定した線 L "
                        'だけを使う。\\n//  方向 side × 線 (LINE1 / LINE2 / STB) ごとに: 接触 = low <= L <= high、近接 ON なら Long low '
                        '> L かつ low − L <= 許容距離 /\\n//  Short high < L かつ L − high <= 許容距離。A = 接触 + 前足終値が取引方向側 (Long '
                        'close[1] > L / Short close[1] < L) + 終値が\\n//  取引方向側 (Long close > L / Short close < L)。B = '
                        '同じ線への先行接触の記録 + close[1] <= L < close (Short は close[1] >= L > close)。\\n//  陽線陰線 ON なら反発足 e '
                        '自身が Long close > open / Short close < open。有効な反発はその線の接触記録を消費する\\n//  (反発しなかった接触は記録を残す)。戻り値 '
                        '[反発成立, 次の記録]。SATS の青 / 赤、P0 / SL0、Zone 資格は使わない\\nf_satHist(int side, float L, bool rec) '
                        '=>\\n    bool ok    = not na(L) and not na(close[1])\\n    bool hit   = ok and low <= L and '
                        'L <= high\\n    bool near  = ok and stSatsNear and (side == 1 ? (low > L and low - L <= '
                        'stSatsNearD) : (high < L and L - high <= stSatsNearD))\\n    bool fresh = ok and (side == 1 '
                        '? close[1] > L : close[1] < L)\\n    bool rA    = (hit or near) and fresh and (side == 1 ? '
                        'close > L : close < L)\\n    bool rB    = rec and ok and (side == 1 ? (close[1] <= L and '
                        'close > L) : (close[1] >= L and close < L))\\n    bool body  = not stSatsBody or (side == 1 '
                        '? close > open : close < open)\\n    bool reb   = (rA or rB) and body\\n    [reb, reb ? '
                        'false : (rec or ((hit or near) and fresh))]\\nvar bool hRecL1 = false\\nvar bool hRecL2 = '
                        'false\\nvar bool hRecL3 = false\\nvar bool hRecS1 = false\\nvar bool hRecS2 = false\\nvar '
                        'bool hRecS3 = false\\n[hL1, nL1] = f_satHist(1, satL1[1], hRecL1)\\n[hL2, nL2] = '
                        'f_satHist(1, satL2[1], hRecL2)\\n[hL3, nL3] = f_satHist(1, satStb[1], hRecL3)\\n[hS1, nS1] '
                        '= f_satHist(-1, satL1[1], hRecS1)\\n[hS2, nS2] = f_satHist(-1, satL2[1], hRecS2)\\n[hS3, '
                        'nS3] = f_satHist(-1, satStb[1], hRecS3)\\nhRecL1 := nL1\\nhRecL2 := nL2\\nhRecL3 := '
                        'nL3\\nhRecS1 := nS1\\nhRecS2 := nS2\\nhRecS3 := nS3\\nvar int hRebBarL = na      // Long '
                        'の最新の反発成立足 (bar_index) と線の種類 (同じ足は LINE1 -> LINE2 -> STB)\\nvar int hRebKL   = 0\\nvar int '
                        'hRebBarS = na\\nvar int hRebKS   = 0\\nif hL1 or hL2 or hL3\\n    hRebBarL := '
                        'bar_index\\n    hRebKL   := hL1 ? 1 : hL2 ? 2 : 3\\nif hS1 or hS2 or hS3\\n    hRebBarS := '
                        "bar_index\\n    hRebKS   := hS1 ? 1 : hS2 ? 2 : 3\\n'\n"
                        "HIST17_NEW = '// XA-16 / XA-17: 準備前の SATS 反発の履歴 (待機 pw* とは独立。毎足・無条件に更新)。足 e の判定には足 e-1 "
                        'で確定した線 L だけを使う。\\n//  方向 side × 線 (LINE1 / LINE2 / STB) ごとに: 接触 = low <= L <= high、近接 ON なら '
                        'Long low > L かつ low − L <= 許容距離 /\\n//  Short high < L かつ L − high <= 許容距離。A = 接触 + '
                        '前足終値が取引方向側 (Long close[1] > L / Short close[1] < L) + 終値が\\n//  取引方向側 (Long close > L / '
                        'Short close < L)。B = 同じ線への先行接触の記録 + close[1] <= L < close (Short は close[1] >= L > '
                        'close)。\\n//  陽線陰線 ON なら反発足 e 自身が Long close > open / Short close < open。SATS の青 / 赤、P0 / '
                        'SL0、Zone 資格は使わない。\\n//  XA-17: 接触記録は接触足 q (bar_index) で持ち、t − q > 即時側の有効本数 になった記録は判定前に捨てる '
                        '(同じ足の新しい接触で\\n//  記録し直せる。保持中の再接触で q を更新しない)。反発の起点 q: A = その足 / B = 記録した q '
                        '(反発時刻へ置き換えない)。有効な\\n//  反発は記録を消費する。戻り値 [反発成立, 起点 q, 次の記録 q]\\nf_satHist(int side, float L, '
                        'int q) =>\\n    bool ok    = not na(L) and not na(close[1])\\n    bool hit   = ok and low '
                        '<= L and L <= high\\n    bool near  = ok and stSatsNear and (side == 1 ? (low > L and low - '
                        'L <= stSatsNearD) : (high < L and L - high <= stSatsNearD))\\n    bool fresh = ok and (side '
                        '== 1 ? close[1] > L : close[1] < L)\\n    bool live  = not na(q) and bar_index - q <= '
                        'stSatsNowN\\n    bool tch   = (hit or near) and fresh\\n    bool rA    = tch and (side == 1 '
                        '? close > L : close < L)\\n    bool rB    = live and ok and (side == 1 ? (close[1] <= L and '
                        'close > L) : (close[1] >= L and close < L))\\n    bool body  = not stSatsBody or (side == 1 '
                        '? close > open : close < open)\\n    bool reb   = (rA or rB) and body\\n    int  qUse  = rA '
                        '? bar_index : q\\n    int  qNext = reb ? na : live ? q : tch ? bar_index : na\\n    [reb, '
                        'qUse, qNext]\\nvar int hTqL1 = na\\nvar int hTqL2 = na\\nvar int hTqL3 = na\\nvar int hTqS1 '
                        '= na\\nvar int hTqS2 = na\\nvar int hTqS3 = na\\n[hL1, qL1, nL1] = f_satHist(1, satL1[1], '
                        'hTqL1)\\n[hL2, qL2, nL2] = f_satHist(1, satL2[1], hTqL2)\\n[hL3, qL3, nL3] = f_satHist(1, '
                        'satStb[1], hTqL3)\\n[hS1, qS1, nS1] = f_satHist(-1, satL1[1], hTqS1)\\n[hS2, qS2, nS2] = '
                        'f_satHist(-1, satL2[1], hTqS2)\\n[hS3, qS3, nS3] = f_satHist(-1, satStb[1], hTqS3)\\nhTqL1 '
                        ':= nL1\\nhTqL2 := nL2\\nhTqL3 := nL3\\nhTqS1 := nS1\\nhTqS2 := nS2\\nhTqS3 := nS3\\n// '
                        '反発の候補 (方向ごと): 起点 q / 成立足 e / 線の種類。t − q > N になった候補は消す (以後も有効にならない)。採用は期限内の\\n// 候補から最新の '
                        'e、同じ e は LINE1 -> LINE2 -> STB (期限外の新しい候補が期限内の候補を隠さない)\\nvar array<int> hQsL = '
                        'array.new_int()\\nvar array<int> hEsL = array.new_int()\\nvar array<int> hKsL = '
                        'array.new_int()\\nvar array<int> hQsS = array.new_int()\\nvar array<int> hEsS = '
