                        'alert.freq_once_per_bar)\\n")\n'
                        '\n'
                        'STRATEGY_EDITS21 = [\n'
                        '    ("header",\n'
                        '     "//  陽線陰線 / 近接 1.0 USD / 逆方向一致 4H・1H は従来の初期値のまま)。即時 OFF・接触期限 ON などは比較・切り戻し用に残す。\\n",\n'
                        '     "//  陽線陰線 / 近接 1.0 USD / 逆方向一致 4H・1H は従来の初期値のまま)。即時 OFF・接触期限 ON などは比較・切り戻し用に残す。\\n"\n'
