                        '     "[hS3, qS3, nS3] = f_satHist(-1, satStb[1], hTqS3)\\n"),\n'
                        '    ("hist", HIST21_OLD, HIST21_NEW),\n'
                        '    ("state", "float pwLineP = na         // その線の価格 (足 t-1 の確定値)\\n",\n'
                        '     "float pwLineP = na         // その線の価格 (足 t-1 の確定値)\\n" + "@@ALERT_STATE@@"),\n'
                        '    ("alert",\n'
                        '     "                    strategy.exit(oXid, oEid, stop = oSL)\\n"\n'
