                        '    ("text", "// XA-7 SATS Pullback の確認表示 (データウィンドウ + 小さな印。永続ラベル・独自アラートは追加しない)\\n",\n'
                        '     "// XA-7 SATS Pullback の確認表示 (データウィンドウ + 小さな印。永続ラベルは追加しない。仮 / 確定アラートは XA-21)\\n"),\n'
