                        ']\n'
                        'STRATEGY_EDITS21 = [(k, a, b.replace("@@ALERT_STATE@@", _alert_state())) for k, a, b in '
                        'STRATEGY_EDITS21]\n'
                        '\n'
                        '\n'
                        '# ---- XA-22: provisional alert once per candidate / wait (Strategy only; applied after '
                        'XA-21) -------------------------------\n'
                        '#  The XA-21 per-5m-bar key stays; a second varip key list (candidate keys) suppresses '
                        're-sending the same candidate on later\n'
                        '#  bars. Key = "Track|path|side|wait": path 1 = SATS pull (wait = pwBar, the prep bar fixed '
                        'at the wait start), 2 = SATS\n'
                        '#  immediate, 3 = Current (wait = -1). Recorded only when the provisional alert() is '
                        'called; released (all keys of a Track)\n'
                        '#  when a formal order is placed on that Track or a formal SATS wait is prepared on it; at '
                        'most PV_KEEP keys (oldest dropped).\n'
                        'PV_KEEP = 200\n'
                        'XA22_HDR = (\n'
                        '    "//  XA-22: 仮アラートの再通知防止。従来の「5分足 1 本につき最大 1 回」に加え、同じ候補・同じ待機には仮を最大 1 回 (足をまたいでも、\\n"\n'
                        '    "//  条件の往復・再接触・再反発・別候補を挟んで戻っても再送しない)。識別キー = Track ID・経路 (SATS 引きつけ / SATS 即時 / '
                        'Current)・\\n"\n'
                        '    "//  方向・待機開始足 (引きつけのみ pwBar)。仮の alert() を呼んだときだけ varip に記録し、その Track '
                        'で正式な発注または正式な待機準備が\\n"\n'
                        '    "//  行われたら解除 (以後の再成立・新しい待機は初回として通知)。確定通知・注文・待機・売買条件・通知文・時間制限は変えない。\\n")\n'
                        '\n'
                        'PVKEY_FNS = (\n'
                        '    "\\n"\n'
                        '    "// XA-22: 仮アラートの候補キー (同じ候補・同じ待機は足をまたいでも 1 回)。\\n"\n'
                        '    "//  キー = \\"Track|経路|方向|待機\\": 経路 1 = SATS 引きつけ (待機 = 待機開始時に固定された pwBar)、2 = SATS 即時、3 '
                        '= Current (待機 = -1)。\\n"\n'
                        '    "//  現在足の time / bar_index や Entry / SL / TP は使わない。仮の alert() を呼んだときだけ gProvKeys '
                        'に追加する\\n"\n'
                        '    "f_stPvKey(int trk, int path, int side, int wbar) =>\\n"\n'
                        '    "    str.tostring(trk) + \\"|\\" + str.tostring(path) + \\"|\\" + str.tostring(side) + '
                        '\\"|\\" + str.tostring(wbar)\\n"\n'
                        '    "\\n"\n'
                        '    "// XA-22: その Track の候補キーを解除する (確定足で、その Track に正式な発注 / 正式な SATS '
                        '待機準備をしたとき)。通知の記録だけを\\n"\n'
                        '    "//  消し、注文・待機・Track の状態は変えない。戻り値 = 解除した件数\\n"\n'
                        '    "f_stPvRelease(int trk) =>\\n"\n'
                        '    "    int    n   = array.size(gProvKeys)\\n"\n'
                        '    "    int    cnt = 0\\n"\n'
                        '    "    string pre = str.tostring(trk) + \\"|\\"\\n"\n'
                        '    "    if n > 0\\n"\n'
                        '    "        for i = n - 1 to 0\\n"\n'
                        '    "            if str.startswith(array.get(gProvKeys, i), pre)\\n"\n'
                        '    "                array.remove(gProvKeys, i)\\n"\n'
                        '    "                cnt += 1\\n"\n'
                        '    "    cnt\\n")\n'
                        '\n'
                        'PROV22_OLD = (\n'
                        '    "//  ・1 本の 5分足につき最大 1 回 (varip gProvAlertBar。確定アラートとは別の状態)。送信後は同じ足で評価・再送しない\\n"\n'
                        '    "bool  stPvSess = stSessOK and (not stUseSess or f_stInSession(timenow))\\n"\n'
                        '    "bool  stPvA    = stAlertProv and is5mChart and not barstate.isconfirmed and oState == '
                        '0 and stPvSess and array.get(gProvAlertBar, 0) != time\\n"\n'
