                        '    "int   pPath    = 0      // XA-22: 1 = SATS 引きつけ / 2 = SATS 即時 / 3 = Current\\n"\n'
                        '    "int   pTrk     = -1     // XA-22: 候補の Track ID\\n"\n'
                        '    "if stPvA and stSats\\n"\n'
