                        'satStb[1])\\n"\n'
                        '    "    pSide := sS\\n"\n'
                        '    "    pPx   := eS\\n"\n'
                        '    "    pSL   := lS\\n"\n'
                        '    "    pTP   := tS\\n"\n'
                        '    "    pPath := aPv\\n"\n'
                        '    "    pTrk  := kPv\\n"\n'
                        '    "if stPvA and not stSats\\n"\n'
                        '    "    [s0, e0, l0, t0, r0] = f_stProvEval()\\n"\n'
                        '    "    pSide := s0\\n"\n'
                        '    "    pPx   := e0\\n"\n'
                        '    "    pSL   := l0\\n"\n'
                        '    "    pTP   := t0\\n"\n'
                        '    "    pPath := 3\\n"\n'
                        '    "    pTrk  := r0\\n"\n'
                        '    "float  pvQty = pSide != 0 ? f_stQty(pSide, pPx, pSL) : na     // 参考値 '
                        '(確定時は判断足の終値で計算し直す)\\n"\n'
                        '    "string pvKey = pSide != 0 ? f_stPvKey(pTrk, pPath, pSide, pPath == 1 ? pwBar : -1) : '
                        '\\"\\"\\n"\n'
                        '    "if stPvA and pSide != 0 and not na(pvQty) and not array.includes(gProvKeys, '
                        'pvKey)\\n"\n'
                        '    "    array.set(gProvAlertBar, 0, time)\\n"\n'
                        '    "    array.push(gProvKeys, pvKey)\\n"\n'
                        '    "    if array.size(gProvKeys) > " + str(PV_KEEP) + "\\n"\n'
                        '    "        array.shift(gProvKeys)\\n"\n'
                        '    "    alert(f_stAlertMsg(\\"仮\\", pSide, pPx, pSL, pTP, not stSats and stModeA, stSats), '
                        'alert.freq_once_per_bar)\\n")\n'
                        '\n'
                        'STRATEGY_EDITS22 = [\n'
                        '    ("header",\n'
                        '     "//  1 本につき仮・確定それぞれ最大 1 回 (varip)。新規発注と通知は既存の時間帯 (初期 9:00〜翌 2:00 JST) の中だけ '
                        '(決済管理は時間外も継続)。\\n",\n'
                        '     "//  1 本につき仮・確定それぞれ最大 1 回 (varip)。新規発注と通知は既存の時間帯 (初期 9:00〜翌 2:00 JST) の中だけ '
                        '(決済管理は時間外も継続)。\\n"\n'
                        '     + XA22_HDR),\n'
                        '    ("state",\n'
