                        '     "varip array<string> gProvKeys = array.new_string()     // XA-22: 仮アラートを送った候補キー '
                        '(Track|経路|方向|待機)。最大 " + str(PV_KEEP) + " 件 (古い順に削除)\\n"),\n'
                        '    ("fns",\n'
                        '     "        alert(f_stAlertMsg(\\"確定\\", side, ePx, sl, tp, isLim, isSats), '
