                        '     "        alert(f_stAlertMsg(\\"確定\\", side, ePx, sl, tp, isLim, isSats), '
                        'alert.freq_all)\\n    send\\n" + PVKEY_FNS),\n'
                        '    ("prov", "//  戻り値: [方向 (0 = なし), 参照価格, SL]\\nf_stProvEval() =>\\n",\n'
                        '     "//  戻り値: [方向 (0 = なし), 参照価格, SL, TP, 候補の Track ID (XA-22: 仮通知の識別用。無ければ '
                        '-1)]\\nf_stProvEval() =>\\n"),\n'
