                        ':= 0\\n    [side, ePx, sl, tpP, trk]\\n"),\n'
                        '    ("prov", "//  戻り値: [方向 (0 = なし), 参照価格 (形成中の終値), SL0, TP0]\\nf_satProvEval(float pc, '
                        'float l1p, float l2p, float stbp) =>\\n"\n'
                        '             "    int   side = 0\\n    float ePx  = na\\n    float sl   = na\\n    float '
                        'tp   = na\\n",\n'
                        '     "//  戻り値: [方向 (0 = なし), 参照価格 (形成中の終値), SL0, TP0, 経路 (XA-22: 1 引きつけ / 2 即時), 候補の Track '
                        'ID]\\n"\n'
                        '     "f_satProvEval(float pc, float l1p, float l2p, float stbp) =>\\n"\n'
                        '     "    int   side = 0\\n    float ePx  = na\\n    float sl   = na\\n    float tp   = '
                        'na\\n    int   path = 0\\n    int   trk  = -1\\n"),\n'
                        '    ("prov", "                tp   := pwTP0\\n    else if stSats and stSatsNow and pwState '
                        '== 0\\n",\n'
                        '     "                tp   := pwTP0\\n                path := 1\\n                trk  := '
                        'pwTrack\\n    else if stSats and stSatsNow and pwState == 0\\n"),\n'
                        '    ("prov", "        [s0, e0, l0, t0] = f_stProvEval()\\n        if s0 != 0\\n",\n'
                        '     "        [s0, e0, l0, t0, r0] = f_stProvEval()\\n        if s0 != 0\\n"),\n'
                        '    ("prov", "                tp   := t0\\n    [side, ePx, sl, tp]\\n",\n'
                        '     "                tp   := t0\\n                path := 2\\n                trk  := '
                        'r0\\n    [side, ePx, sl, tp, path, trk]\\n"),\n'
                        '    ("release",\n'
                        '     "                    f_stConfAlert(pwSide, close, pwSL0, pwTP0, false, true)     // '
