                        'XA-21 確定: 即時の発注 (Entry は判断足の終値、SL0 / TP0 は準備地点の値)\\n",\n'
                        '     "                        f_stConfAlert(side, close, pSL, tpRef, false, true)     // '
                        'XA-21 確定: 即時の発注 (Entry は判断足の終値、SL0 / TP0 は準備地点の値)\\n"\n'
                        '     "                        f_stPvRelease(c.track)     // XA-22: 正式な発注 -> この Track '
                        'の仮通知キーを解除\\n"),\n'
                        '    ("release", "                    pwNPrep  += 1\\n",\n'
                        '     "                    pwNPrep  += 1\\n                    f_stPvRelease(c.track)     // '
                        'XA-22: 正式な待機準備 -> この Track の仮通知キーを解除 (新しい待機は初回を通知)\\n"),\n'
                        '    ("release",\n'
                        '     "                f_stConfAlert(side, stModeA ? oL : close, pSL, tpRef, stModeA, '
                        'false)     // XA-21 確定: Current の発注 (A は指値価格、TP は発注判断時の予定)\\n",\n'
                        '     "                f_stConfAlert(side, stModeA ? oL : close, pSL, tpRef, stModeA, '
                        'false)     // XA-21 確定: Current の発注 (A は指値価格、TP は発注判断時の予定)\\n"\n'
                        '     "                f_stPvRelease(c.track)     // XA-22: 正式な発注 -> この Track '
                        'の仮通知キーを解除\\n"),\n'
                        '    ("prov", PROV22_OLD, PROV22_NEW),\n'
                        ']\n'
                        '\n'
                        '\n'
                        '# ---- XA-23: confirmed labels (Strategy only; applied after XA-22) '
                        '-----------------------------------------------------------\n'
                        '#  One label per formal order, created in the same branches / with the same prices as the '
                        'XA-21 confirmed alert (SATS pull,\n'
                        '#  SATS immediate, Current A limit / B-D market), independent of the alert switches, on '
                        'historical and realtime bars.\n'
                        '#  Dedup by the order id oEid in a `var` key (rolled back together with the label, so a '
                        'recalculated realtime bar cannot lose\n'
                        '#  its label); at most LBL_KEEP labels (oldest deleted). No provisional label.\n'
                        'LBL_KEEP = 50\n'
                        'XA23_HDR = (\n'
                        '    "//  XA-23: 確定ラベル (初期 ON・アラートとは独立)。5分足の確定時に strategy.entry を出した分岐 (SATS 引きつけ / SATS 即時 '
                        '/ Current A 指値・\\n"\n'
                        '    "//  B〜D 成行) で、確定アラートと同じ発注・同じ価格を Long は足の下 (緑系)・Short は足の上 (赤系) に表示 '
                        '(約定確認を待たない。過去足も表示)。\\n"\n'
                        '    "//  同じ注文 (注文 ID) には 1 個、最新 " + str(LBL_KEEP) + " '
                        '個を保持。仮ラベルは無し。売買・アラート・仮の再送防止・時間制限は変えない。\\n")\n'
                        'LBL_INPUTS = (\n'
                        '    \'var string G_STL = "03 · Strategy Labels"\\n\'\n'
                        '    \'stLblConf = input.bool(true, "確定ラベルを表示", group = G_STL,\\n\'\n'
                        '    \'     tooltip = "XA-23: 5分足の確定時に新規 Entry を発注した足に 1 個 (SATS 引きつけ / SATS 即時 / '
                        'Current)。確定アラートと同じ価格。\\\\n" +\\n\'\n'
                        '    \'     "アラートの ON / OFF とは独立。約定通知ではない。過去足にも表示し、最新 \' + str(LBL_KEEP) + \' 個を保持 '
                        '(古い順に削除)。")\\n\')\n'
                        'LBL_STATE = (\n'
                        '    "var array<label>  stConfLbls = array.new<label>()        // XA-23: 確定ラベル (最新 " + '
                        'str(LBL_KEEP) + " 個)\\n"\n'
                        '    "var array<string> stLblEid   = array.new_string(1, \\"\\")   // XA-23: ラベルを出した注文 ID '
                        '(var = ラベルと同じく巻き戻る。同じ注文に 2 個出さない)\\n"\n'
                        '    "int   ST_LBL_KEEP  = " + str(LBL_KEEP) + "\\n"\n'
                        '    "color ST_LBL_LONG  = color.new(color.teal, 0)\\n"\n'
                        '    "color ST_LBL_SHORT = color.new(color.maroon, 0)\\n")\n'
                        'LBL_FNS = (\n'
                        '    "\\n"\n'
                        '    "// XA-23: 確定ラベルの本文。Entry (成行は発注判断時の参考価格 / Current A は指値価格)、SL / TP (SATS は注文の固定 SL0 / '
                        'TP0、Current の TP は\\n"\n'
                        '    "//  発注判断時の予定 TP)、値幅と RR はこの表示価格から計算 (価格・値幅は最小価格刻みの桁、計算できない値は \\"-\\")\\n"\n'
                        '    "f_stLblText(int side, float ePx, float sl, float tp, bool isLim, bool isSats) =>\\n"\n'
                        '    "    float slW = side * (ePx - sl)\\n"\n'
                        '    "    float tpW = side * (tp - ePx)\\n"\n'
                        '    "    float rr  = not na(slW) and slW > 0 and not na(tpW) ? tpW / slW : na\\n"\n'
                        '    "    \\"確定 \\" + (side == 1 ? \\"LONG\\" : \\"SHORT\\") +\\n"\n'
                        '    "     \\"\\\\nEntry：\\" + f_stPx(ePx) + (isLim ? \\"（指値）\\" : \\"（成行・参考）\\") +\\n"\n'
                        '    "     \\"\\\\nSL：\\" + f_stPx(sl) + \\"（\\" + (na(slW) ? \\"-\\" : f_stPx(slW) + '
                        '\\"ドル\\") + \\"）\\" +\\n"\n'
                        '    "     \\"\\\\n\\" + (isSats ? \\"TP\\" : \\"予定TP\\") + \\"：\\" + f_stPx(tp) + \\"（\\" + '
                        '(na(tpW) ? \\"-\\" : f_stPx(tpW) + \\"ドル\\") + \\"）\\" +\\n"\n'
                        '    "     \\"\\\\nRR：\\" + (na(rr) ? \\"-\\" : \\"1:\\" + str.tostring(rr, '
                        '\\"0.00\\"))\\n"\n'
                        '    "\\n"\n'
                        '    "// XA-23: 確定ラベル: 発注した分岐から呼ぶ (表示だけ)。同じ注文 ID (oEid) には 1 個。確定アラートの ON / '
                        'OFF・送信済み状態は見ない\\n"\n'
                        '    "f_stConfLabel(int side, float ePx, float sl, float tp, bool isLim, bool isSats) '
                        '=>\\n"\n'
                        '    "    bool mk = stLblConf and array.get(stLblEid, 0) != oEid\\n"\n'
                        '    "    if mk\\n"\n'
                        '    "        array.set(stLblEid, 0, oEid)\\n"\n'
                        '    "        array.push(stConfLbls, label.new(bar_index, side == 1 ? low : high, '
                        'f_stLblText(side, ePx, sl, tp, isLim, isSats),\\n"\n'
                        '    "             yloc = side == 1 ? yloc.belowbar : yloc.abovebar, color = side == 1 ? '
                        'ST_LBL_LONG : ST_LBL_SHORT,\\n"\n'
                        '    "             textcolor = color.white, style = side == 1 ? label.style_label_up : '
                        'label.style_label_down, size = size.small))\\n"\n'
                        '    "        if array.size(stConfLbls) > ST_LBL_KEEP\\n"\n'
                        '    "            label.delete(array.shift(stConfLbls))\\n"\n'
                        '    "    mk\\n")\n'
                        '\n'
                        'STRATEGY_EDITS23 = [\n'
                        '    ("header",\n'
                        '     "//  行われたら解除 (以後の再成立・新しい待機は初回として通知)。確定通知・注文・待機・売買条件・通知文・時間制限は変えない。\\n",\n'
                        '     "//  行われたら解除 (以後の再成立・新しい待機は初回として通知)。確定通知・注文・待機・売買条件・通知文・時間制限は変えない。\\n" + XA23_HDR),\n'
                        '    ("input",\n'
                        '     \'     "1 本の 5分足につき最大 1 回 (仮アラートの有無・ON / OFF とは独立)。通知の重複防止は発注を止めない。")\\n\',\n'
                        '     \'     "1 本の 5分足につき最大 1 回 (仮アラートの有無・ON / OFF とは独立)。通知の重複防止は発注を止めない。")\\n\' + '
                        'LBL_INPUTS),\n'
                        '    ("state",\n'
                        '     "varip array<string> gProvKeys = array.new_string()     // XA-22: 仮アラートを送った候補キー '
                        '(Track|経路|方向|待機)。最大 200 件 (古い順に削除)\\n",\n'
                        '     "varip array<string> gProvKeys = array.new_string()     // XA-22: 仮アラートを送った候補キー '
                        '(Track|経路|方向|待機)。最大 200 件 (古い順に削除)\\n" + LBL_STATE),\n'
                        '    ("fns", "                cnt += 1\\n    cnt\\n", "                cnt += 1\\n    '
                        'cnt\\n" + LBL_FNS),\n'
                        '    ("label",\n'
                        '     "                    f_stPvRelease(pwTrack)     // XA-22: 正式な発注 -> この Track の仮通知キーを解除 '
                        '(通知の記録だけ)\\n",\n'
                        '     "                    f_stPvRelease(pwTrack)     // XA-22: 正式な発注 -> この Track の仮通知キーを解除 '
                        '(通知の記録だけ)\\n"\n'
                        '     "                    f_stConfLabel(pwSide, close, pwSL0, pwTP0, false, true)     // '
                        'XA-23 確定ラベル: 確定アラートと同じ値\\n"),\n'
                        '    ("label",\n'
                        '     "                        f_stPvRelease(c.track)     // XA-22: 正式な発注 -> この Track '
                        'の仮通知キーを解除\\n",\n'
                        '     "                        f_stPvRelease(c.track)     // XA-22: 正式な発注 -> この Track '
                        'の仮通知キーを解除\\n"\n'
                        '     "                        f_stConfLabel(side, close, pSL, tpRef, false, true)     // '
                        'XA-23 確定ラベル: 確定アラートと同じ値\\n"),\n'
                        '    ("label",\n'
                        '     "\\n                f_stPvRelease(c.track)     // XA-22: 正式な発注 -> この Track '
                        'の仮通知キーを解除\\n",\n'
                        '     "\\n                f_stPvRelease(c.track)     // XA-22: 正式な発注 -> この Track '
                        'の仮通知キーを解除\\n"\n'
                        '     "                f_stConfLabel(side, stModeA ? oL : close, pSL, tpRef, stModeA, '
                        'false)     // XA-23 確定ラベル: 確定アラートと同じ値\\n"),\n'
                        ']\n'
                        '\n'
