                       '          "2700.000 -> one evidence (3 points, 1 category); 0.001 apart -> both counted (6 + '
                       '1, 2 categories)",\n'
                       '          (m0["score"], m0["cat"]) == (3.0, 1) and (m1["score"], m1["cat"]) == (7.0, 2))\n'
                       '    st = git("status", "--porcelain").split("\\n")\n'
                       '    mod = set(git("diff", "--name-only", A, "--").split()) | {l[3:] for l in st if '
                       'l.startswith("??")}\n'
                       '    mod -= {"tests/__pycache__/"}\n'
                       '    mod = {m for m in mod if not __import__("xal_build").ok(m) and m not in '
                       '__import__("btl_build").NEW_TESTS}     # XL-1 (Gold Long, new) / BTL-1 new tests: exact\n'
                       '    others = [p for p in os.listdir(ROOT) if p.endswith(".pine") and p not in (xb.VIS_PATH, '
                       'xb.STR_PATH) and not __import__("xal_build").ok(p)]\n'
                       '    check("XF-07 vs a33d2b0 only the Gold Visual / Strategy, xa_build, xae_sim, cad_sim and '
                       'cad_adapt change; every other Pine "\n'
                       '          "file (Engines incl. ZoneEnginePracticalXAUUSD, other symbols) byte-identical",\n'
                       '          {m for m in mod if not (m in __import__("sx_build").TOUCHED and '
                       '__import__("cad_adapt").later_ok(m, A))}   # SX-1: exact only\n'
                       '          <= {xb.VIS_PATH, xb.STR_PATH, xb.ENG_PATH, "tests/xa_build.py", '
                       '"tests/xae_sim.py", "tests/cad_sim.py", "tests/cad_adapt.py",\n'
                       '                  "tests/xas_sim.py", "tests/sats_src/f_satBand.txt", '
                       '"tests/sats_src/README.txt"}   # XA-7 (pinned in xas_sim)\n'
                       '          and {xb.VIS_PATH, xb.STR_PATH} <= mod and not [p for p in others if rd(p) != '
                       'git("show", f"{A}:{p}")\n'
                       '                                                         and not (p == xb.ENG_PATH and E == '
                       'git("show", f"{A}:{p}"))], str(sorted(mod)))   # XA-6: Engine exact\n'
                       '    muts = [V5.replace(ds_new, ds_old), S5.replace(be[1], be[0]), S5.replace(be[3], be[2]),\n'
                       "            V5.replace('dsDist = input.float(0.0,', 'dsDist = input.float(0.5,')]\n"
                       '    check("XF-08 mutations do not strip back to a33d2b0: Day/Swing back to Separate, '
                       'Breakeven OFF, Trigger 10, Merge Distance 0.5",\n'
                       '          all(m != t and f(m) != base for m, t, f, base in zip(muts, [V5, S5, S5, V5],\n'
                       '                                                                 [xb.strip_visual5, '
                       'xb.strip_strategy5, xb.strip_strategy5, xb.strip_visual5],\n'
                       '                                                                 [VA, SA, SA, VA])))\n'
                       '\n'
                       '\n'
                       '# ---- XA-6: Role Reversal Mode '
                       '---------------------------------------------------------------------------------------------\n'
                       'ST_A, ST_S, ST_R, ST_B = 0, 1, 2, 3\n'
                       '\n'
                       '\n'
                       'def upd(t, role_on_break, eval_bar, bc, bh, bl, buf=10.0, fcd=5.0, reset=True, close=None, '
                       'variant=None):\n'
                       '    """port of f_updateTrack (both modes); t = dict(top, bottom, state, lastRole, breakDir, '
                       'retested, flipped, flipDir)."""\n'
                       '    ev, prev, handled = 0, t["state"], False\n'
                       '    ev_state = (ST_S if t["lastRole"] > 0 else ST_R if t["lastRole"] < 0 else ST_A) if prev '
                       '== ST_A else prev\n'
                       '    nat = lambda: ST_S if close > t["top"] else ST_R if close < t["bottom"] else ST_A\n'
                       '    if eval_bar and role_on_break:\n'
                       '        if ev_state == ST_R and (bc >= t["top"] + buf if variant == "non_strict" else bc > '
                       't["top"] + buf):\n'
                       '            t.update(state=ST_S, breakDir=1, retested=variant == "retest_on_break" and bl <= '
                       't["top"], flipped=False, flipDir=0)\n'
                       '            handled, ev = True, 1\n'
                       '        elif ev_state == ST_S and bc < t["bottom"] - buf:\n'
                       '            t.update(state=ST_R, breakDir=-1, retested=t["retested"] if variant == '
                       '"keep_retest" else False, flipped=False, flipDir=0)\n'
                       '            handled, ev = True, -1\n'
                       '        elif t["breakDir"] == 1:\n'
                       '            handled = True\n'
                       '            if not t["retested"]:\n'
                       '                if bl <= t["top"] and bh >= t["bottom"]:\n'
                       '                    t["retested"] = True\n'
                       '                    if variant == "flip_on_retest_bar" and bc >= t["top"] + fcd:\n'
                       '                        t.update(flipped=True, flipDir=1, breakDir=0, retested=False)\n'
                       '                        ev = 2\n'
                       '            elif bc >= t["top"] + fcd:\n'
                       '                t.update(flipped=True, flipDir=1, breakDir=0, retested=False)\n'
                       '                ev = 2\n'
                       '        elif t["breakDir"] == -1:\n'
                       '            handled = True\n'
                       '            if not t["retested"]:\n'
                       '                if bh >= t["bottom"] and bl <= t["top"]:\n'
                       '                    t["retested"] = True\n'
                       '            elif bc <= t["bottom"] - fcd:\n'
                       '                t.update(flipped=True, flipDir=-1, breakDir=0, retested=False)\n'
                       '                ev = -2\n'
                       '        if variant == "natural" and ev == 0:\n'
                       '            t["state"] = ST_S if bc > t["top"] else ST_R if bc < t["bottom"] else '
                       't["state"]\n'
                       '    elif eval_bar:\n'
                       '        if ev_state == ST_R and bc > t["top"] + buf:\n'
                       '            t.update(state=ST_B, breakDir=1, retested=False, flipped=False, flipDir=0)\n'
                       '            handled, ev = True, 1\n'
                       '        elif ev_state == ST_S and bc < t["bottom"] - buf:\n'
                       '            t.update(state=ST_B, breakDir=-1, retested=False, flipped=False, flipDir=0)\n'
                       '            handled, ev = True, -1\n'
                       '        elif prev == ST_B and t["breakDir"] == 1:\n'
                       '            handled = True\n'
                       '            if bc < t["bottom"] - buf:\n'
                       '                t.update(breakDir=0, retested=False)\n'
                       '                if reset:\n'
                       '                    t["state"] = nat()\n'
                       '            elif not t["retested"]:\n'
                       '                if bl <= t["top"] and bh >= t["bottom"]:\n'
                       '                    t["retested"] = True\n'
                       '            elif bc >= t["top"] + fcd:\n'
                       '                t.update(flipped=True, flipDir=1, state=ST_S, breakDir=0, retested=False)\n'
                       '                ev = 2\n'
                       '        elif prev == ST_B and t["breakDir"] == -1:\n'
                       '            handled = True\n'
                       '            if bc > t["top"] + buf:\n'
                       '                t.update(breakDir=0, retested=False)\n'
                       '                if reset:\n'
                       '                    t["state"] = nat()\n'
                       '            elif not t["retested"]:\n'
                       '                if bh >= t["bottom"] and bl <= t["top"]:\n'
                       '                    t["retested"] = True\n'
                       '            elif bc <= t["bottom"] - fcd:\n'
                       '                t.update(flipped=True, flipDir=-1, state=ST_R, breakDir=0, retested=False)\n'
                       '                ev = -2\n'
                       '    if not handled and t["state"] == ST_A:\n'
                       '        t["state"] = nat()\n'
                       '    if t["state"] == ST_S:\n'
                       '        t["lastRole"] = 1\n'
                       '    elif t["state"] == ST_R:\n'
                       '        t["lastRole"] = -1\n'
                       '    return ev\n'
                       '\n'
                       '\n'
                       'def track(state, top=2712.0, bottom=2700.0):\n'
                       '    return dict(top=top, bottom=bottom, state=state, lastRole=1 if state == ST_S else -1 if '
                       'state == ST_R else 0, breakDir=0,\n'
                       '                retested=False, flipped=False, flipDir=0, id=7)\n'
                       '\n'
                       '\n'
                       'def run(t, bars, mode=True, **kw):\n'
                       '    """bars: (eval, close, high, low). Returns list of (ev, state, flipped, retested, '
                       'flipBonus)."""\n'
                       '    out = []\n'
                       '    for e, c, h, l in bars:\n'
                       '        ev = upd(t, mode, e, c, h, l, close=c, **kw)\n'
                       '        out.append((ev, t["state"], t["flipped"], t["retested"], 1.0 if t["flipped"] else '
                       '0.0))\n'
                       '    return out\n'
                       '\n'
                       '\n'
                       'def gate_xa6():\n'
                       '    E6, V6, S6 = rd(xb.ENG_PATH), xb.strip_visual7(rd(xb.VIS_PATH)) or "", '
                       'xb.strip_strategy7(rd(xb.STR_PATH)) or ""   # XA-6 layer (later edits reverted exactly; '
                       'pinned in xas_sim)\n'
                       '    B = "cbb996d"\n'
                       '    E1, VB, SB = xb.show(B, xb.ENG_PATH), xb.show(B, xb.VIS_PATH), xb.show(B, xb.STR_PATH)\n'
                       '    check("XR-01 XA-6: Engine == xa_build.build_engine() (version 1 + XA-6), Visual / '
