                       'branch `if evalBar and c.roleOnBreak`; "\n'
                       '          "the previous branch is byte-identical under `else if evalBar` (roleOnBreak = '
                       'false -> the version 1 transitions, "\n'
                       '          "events, flipped / Flip Bonus and Touch exactly); no other Engine line (Zone '
                       'generation / merge / width / sources / "\n'
                       '          "scoring / lifetime / RN / Track matching / Touch) changes",\n'
                       '          new_block[len("    else "):] == old_block[len("    "):]\n'
                       '          and set(ch) <= role_lines | {"if evalBar", "bool   roleOnBreak        = false   // '
                       'XA-6: false = Retest Confirmed (version 1 と同じ) / true = Confirmed Break"}\n'
                       '          and "    bool   roleOnBreak        = false" in E6 and func(E6, '
                       '"f_updateTouch(ZoneTrack t, Zone z, ZoneCfg c) =>") == func(E1, "f_updateTouch(ZoneTrack t, '
                       'Zone z, ZoneCfg c) =>"),\n'
                       '          str([l for l in ch if l not in role_lines][:4]))\n'
                       '    vd, sd, vdb, sdb = input_decls(V6), input_decls(S6), input_decls(VB), input_decls(SB)\n'
                       '    cv = sorted(l for l in es.changed_code(VB, V6) if l)\n'
                       '    cs = sorted(l for l in es.changed_code(SB, S6) if l)\n'
                       '    check("XR-03 scripts delta (both identical): import ZoneEnginePracticalXAUUSD/1 -> /2, '
                       'the Role Reversal Mode input (default "\n'
                       '          "Confirmed Break, options Retest Confirmed / Confirmed Break), the resetOnReclaim '
                       'tooltip (used only by Retest Confirmed), "\n'
                       '          "zoneCfg.roleOnBreak := roleMode == \\"Confirmed Break\\"; Visual / Strategy pass '
                       'the same Engine setting",\n'
                       '          cv == cs and vd["roleMode"] == sd["roleMode"] and vd["resetOnReclaim"] == '
                       'sd["resetOnReclaim"]\n'
                       '          and input_values(V6)["roleMode"] == \'"Confirmed Break"\' and \'options = ["Retest '
                       'Confirmed", "Confirmed Break"]\' in vd["roleMode"]\n'
                       '          and "Retest Confirmed のときだけ使う" in vd["resetOnReclaim"] and '
                       'input_values(V6)["resetOnReclaim"] == "true"\n'
                       '          and re.findall(r"^import .*$", V6 + S6, re.M) == [xb.IMPORT_XAE2.strip()] * 2\n'
                       '          and re.findall(r"^zoneCfg\\.\\w+\\s*:=.*$", V6, re.M) == '
                       're.findall(r"^zoneCfg\\.\\w+\\s*:=.*$", S6, re.M)\n'
                       '          and \'zoneCfg.roleOnBreak          := roleMode == "Confirmed Break"\' in V6\n'
                       '          and set(vd) - set(vdb) == {"roleMode"} and set(sd) - set(sdb) == {"roleMode"}\n'
                       '          and not [n for n in vdb if n != "resetOnReclaim" and vdb[n] != vd[n]] and not [n '
                       'for n in sdb if n != "resetOnReclaim" and sdb[n] != sd[n]],\n'
                       '          str((cv[:3], cs[:3])))\n'
                       '    req = lambda t: re.findall(r"^.*request\\.\\w+\\(.*$", t, re.M)\n'
                       '    feed = lambda t: re.findall(r"^.*\\b(?:brClose|brHigh|brLow|brEval)\\b.*$", '
                       'code_only(t), re.M)\n'
