                       '2721.0, 2722, 2711)]),\n'
                       '             run(track(ST_R), [(True, 2722.0, 2723, 2711)]), run(track(ST_R), [(False, '
                       '2740.0, 2741, 2735)]),\n'
                       '             run(track(ST_S), [(True, 2690.0, 2701, 2689)])]\n'
                       '    check("XR-07 no change for a wick only (high 2730, close 2715), a close short of the '
                       'buffer (2721), a close exactly at the "\n'
                       '          "boundary (2722.000 / 2690.000, strict), or an unconfirmed / non-evaluation bar '
                       '(close 2740)",\n'
                       '          all(r[0][0] == 0 and r[0][1] in (ST_R, ST_S) for r in nochg) and nochg[0][0][1] == '
                       'ST_R and nochg[4][0][1] == ST_S)\n'
                       '    seq = run(track(ST_R), [(True, 2723.0, 2724, 2705), (True, 2718.0, 2719, 2711), (True, '
                       '2716.0, 2717, 2713),\n'
                       '                            (True, 2717.0, 2718, 2714), (True, 2720.0, 2721, 2716)])\n'
                       '    check("XR-08 Break bar overlapping the zone is not a retest (retested false); the next '
                       'overlapping bar records the retest and "\n'
                       '          "does not confirm even with close 2718 >= 2717; a later bar below 2717 does not '
                       'confirm; close 2717 confirms once "\n'
                       '          "(Flip +2, flipped, Flip Bonus from that bar); no second Flip afterwards",\n'
                       '          [x[0] for x in seq] == [1, 0, 0, 2, 0] and [x[3] for x in seq] == [False, True, '
                       'True, False, False]\n'
