                       'seq] == [0.0, 0.0, 0.0, 1.0, 1.0]\n'
                       '          and all(x[1] == ST_S for x in seq))\n'
                       '    opp = run(track(ST_R), [(True, 2723.0, 2724, 2716), (True, 2714.0, 2715, 2708), (True, '
