                       '2695.0, 2698, 2694)])\n'
                       '    check("XR-09 opposite clear Break while pending: up break, retest recorded, then close '
                       '2688 < 2690 -> RESIST, Break -1, the "\n'
                       '          "old retest discarded (no immediate confirmation at 2690 <= 2695 without a new '
                       'retest); new retest at 2701 overlap, "\n'
