                       '          "SUPPORT (no natural reversal; the Track keeps its id)", all(x[1] == ST_S for x in '
                       'back) and [x[0] for x in back] == [1, 0, 0, 0])\n'
                       '    o = run(track(ST_R), [(True, 2723.0, 2724, 2716), (True, 2714.0, 2715, 2708), (True, '
                       '2718.0, 2719, 2715)], mode=False)\n'
                       '    r = run(track(ST_R), [(True, 2723.0, 2724, 2716), (True, 2680.0, 2690, 2679)], '
                       'mode=False)\n'
